/* Worked example                                                             */

export interface WorkedExampleStep {
  id: string;
  title?: React.ReactNode;
  content?: React.ReactNode;
  rationale?: React.ReactNode;
}

export interface WorkedExampleLabels {
  example: string;
  problemPending: string;
  step: (position: number, total: number) => string;
  stepPending: string;
  rationale: string;
  nextStep: string;
  complete: string;
  noSteps: string;
}

const workedExampleDefaults: WorkedExampleLabels = {
  example: "Worked example",
  problemPending: "The example problem is still loading.",
  step: (position, total) => `Step ${position} of ${total}`,
  stepPending: "Step content is still loading.",
  rationale: "Why this step?",
  nextStep: "Show next step",
  complete: "All steps are visible.",
  noSteps: "No solution steps yet.",
};

export interface WorkedExampleProps
  extends Omit<React.ComponentPropsWithoutRef<"section">, "children" | "title"> {
  problem?: React.ReactNode;
  description?: React.ReactNode;
  steps?: WorkedExampleStep[];
  summary?: React.ReactNode;
  mode?: "static" | "progressive";
  revealedStepCount?: number;
  defaultRevealedStepCount?: number;
  onRevealedStepCountChange?: (count: number) => void;
  disabled?: boolean;
  labels?: Partial<WorkedExampleLabels>;
}

/** A solved process. Progressive disclosure is navigation through content, never assessment. */
export const WorkedExample = React.forwardRef<HTMLElement, WorkedExampleProps>(
  function WorkedExample(
    {
      problem,
      description,
      steps = [],
      summary,
      mode = "static",
      revealedStepCount: revealedCountProp,
      defaultRevealedStepCount = 1,
      onRevealedStepCountChange,
      disabled = false,
      labels,
      className,
      "aria-label": ariaLabel,
      "aria-labelledby": ariaLabelledby,
      ...props
    },
    ref,
  ) {
    const copy = { ...workedExampleDefaults, ...labels };
    const titleId = React.useId();
    const stepsId = React.useId();
    const [requestedCount, setRequestedCount] = useControllable(
      revealedCountProp,
      defaultRevealedStepCount,
      onRevealedStepCountChange,
    );
    const visibleCount = mode === "static"
      ? steps.length
      : Math.max(0, Math.min(requestedCount, steps.length));
    const visibleSteps = steps.slice(0, visibleCount);
    const canReveal = mode === "progressive" && visibleCount < steps.length;

    return (
      <section
        ref={ref}
        data-slot="worked-example"
        data-mode={mode}
        aria-label={ariaLabel ?? (ariaLabelledby === undefined && problem === undefined ? copy.example : undefined)}
        aria-labelledby={ariaLabelledby ?? (problem !== undefined ? titleId : undefined)}
        className={cn("w-full max-w-2xl", className)}
        {...props}
      >
        <Card>
          <CardHeader>
            <CardTitle id={titleId}>{problem ?? copy.problemPending}</CardTitle>
            {description !== undefined ? <CardDescription>{description}</CardDescription> : null}
          </CardHeader>
          <CardContent className="flex flex-col gap-4">
            {steps.length === 0 ? (
              <p className="rounded-md border p-4 text-sm text-muted-foreground">{copy.noSteps}</p>
            ) : (
              <ol id={stepsId} className="flex flex-col gap-3" aria-live="polite">
                {visibleSteps.map((step, index) => (
                  <li key={step.id} className="rounded-md border p-4">
                    <p className="text-xs font-medium text-muted-foreground">
                      {copy.step(index + 1, steps.length)}
                    </p>
                    {step.title !== undefined ? (
                      <h3 className="mt-1 text-sm font-medium text-foreground">{step.title}</h3>
                    ) : null}
                    <div className="mt-2 text-sm leading-relaxed text-foreground">
                      {step.content ?? copy.stepPending}
                    </div>
                    {step.rationale !== undefined ? (
                      <div className="mt-3 border-t pt-3 text-sm">
                        <p className="mb-1 font-medium text-foreground">{copy.rationale}</p>
                        <div className="text-muted-foreground">{step.rationale}</div>
                      </div>
                    ) : null}
                  </li>
                ))}
              </ol>
            )}
            {!canReveal && steps.length > 0 && summary !== undefined ? (
              <div className="rounded-md bg-muted p-4 text-sm">
                <span className="sr-only">{copy.complete} </span>
                {summary}
              </div>
            ) : null}
          </CardContent>
          {canReveal ? (
            <CardFooter>
              <Button
                type="button"
                aria-controls={stepsId}
                disabled={disabled}
                onClick={() => setRequestedCount(visibleCount + 1)}
              >
                {copy.nextStep}
              </Button>
            </CardFooter>
          ) : null}
        </Card>
      </section>
    );
  },
);

/* -------------------------------------------------------------------------- */
/* Completion problem                                                         */

export interface CompletionWorkedStep {
  id: string;
  kind: "worked";
  title?: React.ReactNode;
  content?: React.ReactNode;
  rationale?: React.ReactNode;
}

export interface CompletionMissingStep {
  id: string;
  kind: "completion";
  title?: React.ReactNode;
  prompt?: React.ReactNode;
  acceptedAnswers?: string[];
  caseSensitive?: boolean;
  multiline?: boolean;
  placeholder?: string;
  feedback?: React.ReactNode;
}

export type CompletionProblemStep = CompletionWorkedStep | CompletionMissingStep;
export type CompletionProblemValue = Record<string, string>;
export type CompletionStepStatus = "correct" | "incorrect" | "ungraded";

export interface CompletionProblemResult {
  value: CompletionProblemValue;
  status: "correct" | "incorrect" | "partial" | "ungraded";
  steps: Record<string, CompletionStepStatus>;
}

export interface CompletionProblemLabels {
  activity: string;
  problemPending: string;
  step: (position: number, total: number) => string;
  workedStep: string;
  missingStep: string;
  response: (position: number) => string;
  submit: string;
  correct: string;
  incorrect: string;
  ungraded: string;
  acceptedAnswer: string;
  noSteps: string;
  incomplete: string;
}

const completionDefaults: CompletionProblemLabels = {
  activity: "Completion problem",
  problemPending: "The problem is still loading.",
  step: (position, total) => `Step ${position} of ${total}`,
  workedStep: "Worked step",
  missingStep: "Complete this step",
  response: (position) => `Your response for step ${position}`,
  submit: "Check responses",
  correct: "Correct",
  incorrect: "Needs revision",
  ungraded: "Submitted for review",
  acceptedAnswer: "Accepted answer",
  noSteps: "No problem steps yet.",
  incomplete: "Complete every missing step before submitting.",
};

function normalize(value: string, caseSensitive: boolean): string {
  const normalized = value.trim().replace(/\s+/g, " ");
  return caseSensitive ? normalized : normalized.toLocaleLowerCase();
}

function evaluateCompletion(
  steps: CompletionProblemStep[],
  value: CompletionProblemValue,
): CompletionProblemResult {
  const outcomes: Record<string, CompletionStepStatus> = {};
  for (const step of steps) {
    if (step.kind !== "completion") continue;
    if (!step.acceptedAnswers || step.acceptedAnswers.length === 0) {
      outcomes[step.id] = "ungraded";
      continue;
    }
    const candidate = normalize(value[step.id] ?? "", step.caseSensitive ?? false);
    outcomes[step.id] = step.acceptedAnswers.some(
      (answer) => normalize(answer, step.caseSensitive ?? false) === candidate,
    ) ? "correct" : "incorrect";
  }
  const statuses = Object.values(outcomes);
  const graded = statuses.filter((status) => status !== "ungraded");
  const correctCount = graded.filter((status) => status === "correct").length;
  const status = graded.length === 0
    ? "ungraded"
    : statuses.some((stepStatus) => stepStatus === "ungraded")
      ? "partial"
    : correctCount === graded.length
      ? "correct"
      : correctCount === 0
          ? "incorrect"
          : "partial";
  return { value: { ...value }, status, steps: outcomes };
}

export interface CompletionProblemProps
  extends Omit<
    React.ComponentPropsWithoutRef<"section">,
    "children" | "defaultValue" | "onSubmit" | "title"
  > {
  problem?: React.ReactNode;
  description?: React.ReactNode;
  steps?: CompletionProblemStep[];
  value?: CompletionProblemValue;
  defaultValue?: CompletionProblemValue;
  onValueChange?: (value: CompletionProblemValue) => void;
  onSubmit?: (result: CompletionProblemResult) => void;
  disabled?: boolean;
  labels?: Partial<CompletionProblemLabels>;
}

/** A partly solved sequence with text gaps and per-step informative feedback. */
export const CompletionProblem = React.forwardRef<HTMLElement, CompletionProblemProps>(
  function CompletionProblem(
    {
      problem,
      description,
      steps = [],
      value: valueProp,
      defaultValue = {},
      onValueChange,
      onSubmit,
      disabled = false,
      labels,
      className,
      "aria-label": ariaLabel,
      "aria-labelledby": ariaLabelledby,
      ...props
    },
    ref,
  ) {
    const copy = { ...completionDefaults, ...labels };
    const titleId = React.useId();
    const errorId = React.useId();
    const [value, setValue] = useControllable(valueProp, defaultValue, onValueChange);
    const [result, setResult] = React.useState<CompletionProblemResult>();
    const missingSteps = steps.filter(
      (step): step is CompletionMissingStep => step.kind === "completion",
    );
    const complete = missingSteps.length > 0 && missingSteps.every(
      (step) => (value[step.id] ?? "").trim().length > 0,
    );

    const update = (id: string, response: string) => setValue({ ...value, [id]: response });
    const submit = (event: React.FormEvent) => {
      event.preventDefault();
      if (!complete || disabled || result !== undefined) return;
      const next = evaluateCompletion(steps, value);
      setResult(next);
      onSubmit?.(next);
    };

    return (
      <section
        ref={ref}
        data-slot="completion-problem"
        data-result={result?.status}
        aria-label={ariaLabel ?? (ariaLabelledby === undefined && problem === undefined ? copy.activity : undefined)}
        aria-labelledby={ariaLabelledby ?? (problem !== undefined ? titleId : undefined)}
        className={cn("w-full max-w-2xl", className)}
        {...props}
      >
        <Card>
          <CardHeader>
            <CardTitle id={titleId}>{problem ?? copy.problemPending}</CardTitle>
            {description !== undefined ? <CardDescription>{description}</CardDescription> : null}
          </CardHeader>
          {/* Card's own gap only separates direct children; both slots live inside this form. */}
          <form onSubmit={submit} className="flex flex-col gap-6">
            <CardContent>
              {steps.length === 0 ? (
                <p className="rounded-md border p-4 text-sm text-muted-foreground">{copy.noSteps}</p>
              ) : (
                <ol className="flex flex-col gap-3">
                  {steps.map((step, index) => {
                    const position = index + 1;
                    const status = result?.steps[step.id];
                    const inputId = `${titleId}-response-${index}`;
                    const feedbackId = `${inputId}-feedback`;
                    return (
                      <li key={step.id} data-kind={step.kind} data-status={status} className="rounded-md border p-4">
                        <p className="text-xs font-medium text-muted-foreground">
                          {copy.step(position, steps.length)} · {step.kind === "worked" ? copy.workedStep : copy.missingStep}
                        </p>
                        {step.title !== undefined ? <h3 className="mt-1 text-sm font-medium">{step.title}</h3> : null}
                        {step.kind === "worked" ? (
                          <>
                            {step.content !== undefined ? <div className="mt-2 text-sm">{step.content}</div> : null}
                            {step.rationale !== undefined ? <div className="mt-2 text-sm text-muted-foreground">{step.rationale}</div> : null}
                          </>
                        ) : (
                          <div className="mt-3 flex flex-col gap-2">
                            <Label htmlFor={inputId}>{step.prompt ?? copy.response(position)}</Label>
                            {step.multiline ? (
                              <Textarea
                                id={inputId}
                                value={value[step.id] ?? ""}
                                placeholder={step.placeholder}
                                onChange={(event) => update(step.id, event.target.value)}
                                disabled={disabled || result !== undefined}
                                aria-invalid={status === "incorrect" || undefined}
                                aria-describedby={status !== undefined ? feedbackId : undefined}
                              />
                            ) : (
                              <Input
                                id={inputId}
                                value={value[step.id] ?? ""}
                                placeholder={step.placeholder}
                                onChange={(event) => update(step.id, event.target.value)}
                                disabled={disabled || result !== undefined}
                                aria-invalid={status === "incorrect" || undefined}
                                aria-describedby={status !== undefined ? feedbackId : undefined}
                              />
                            )}
                            {status !== undefined ? (
                              <div id={feedbackId} role="status" className="rounded-md bg-muted p-3 text-sm">
                                <p className="font-medium">
                                  {status === "correct" ? copy.correct : status === "incorrect" ? copy.incorrect : copy.ungraded}
                                </p>
                                {step.feedback !== undefined ? <div className="mt-1 text-muted-foreground">{step.feedback}</div> : null}
                                {status === "incorrect" && step.acceptedAnswers?.[0] !== undefined ? (
                                  <p className="mt-1 text-muted-foreground">{copy.acceptedAnswer}: <span className="font-medium text-foreground">{step.acceptedAnswers[0]}</span></p>
                                ) : null}
                              </div>
                            ) : null}
                          </div>
                        )}
                      </li>
                    );
                  })}
                </ol>
              )}
              {missingSteps.length > 0 && !complete && result === undefined ? (
                <p id={errorId} className="mt-3 text-sm text-muted-foreground">{copy.incomplete}</p>
              ) : null}
            </CardContent>
            {missingSteps.length > 0 && result === undefined ? (
              <CardFooter>
                <Button type="submit" disabled={!complete || disabled} aria-describedby={!complete ? errorId : undefined}>
                  {copy.submit}
                </Button>
              </CardFooter>
            ) : null}
          </form>
        </Card>
      </section>
    );
  },
);

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

import * as React from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { cn } from "@/lib/didact/cn";

function useControllable<T>(
  controlled: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T) => void] {
  const isControlled = controlled !== undefined;
  const [internalValue, setInternalValue] = React.useState(defaultValue);
  const value = controlled ?? internalValue;
  const setValue = React.useCallback(
    (next: T) => {
      if (!isControlled) setInternalValue(next);
      onChange?.(next);
    },
    [isControlled, onChange],
  );
  return [value, setValue];
}

export interface NumericTolerance {
  /** Maximum difference in the same units as the expected value. */
  absolute?: number;
  /** Maximum proportional difference, where 0.02 means 2% of the expected value. */
  relative?: number;
  /** Whether one or every declared tolerance must pass. Defaults to `either`. */
  mode?: "either" | "both";
}

export type NumericQuestionRule =
  | { kind: "value"; value: number; tolerance?: NumericTolerance }
  | {
      kind: "range";
      min?: number;
      max?: number;
      includeMin?: boolean;
      includeMax?: boolean;
    };

export interface NumericQuestionUnit {
  /** Canonical, visible unit. */
  symbol: string;
  /** `display` keeps the unit outside the input; `required` asks the learner to type it. */
  policy: "display" | "required";
  /** Additional spellings accepted when the policy is `required`. */
  aliases?: string[];
  caseSensitive?: boolean;
}

export interface NumericQuestionNumberFormat {
  decimalSeparator?: "." | ",";
  allowExponent?: boolean;
}

export type NumericQuestionStatus = "correct" | "incorrect" | "ungraded";
export type NumericQuestionReason =
  | "matched"
  | "outside-tolerance"
  | "outside-range"
  | "invalid-number"
  | "unit-mismatch"
  | "ungraded";

export interface NumericQuestionResult {
  rawValue: string;
  value: number | null;
  status: NumericQuestionStatus;
  reason: NumericQuestionReason;
  unit?: string;
}

export interface NumericQuestionLabels {
  activity: string;
  promptPending: string;
  response: string;
  responsePlaceholder: string;
  displayUnit: (unit: string) => string;
  requiredUnit: (unit: string) => string;
  submit: string;
  correct: string;
  incorrect: string;
  ungraded: string;
  invalidNumber: string;
  unitMismatch: (unit: string) => string;
  expectedValue: (value: string) => string;
  expectedRange: (range: string) => string;
}

const defaultLabels: NumericQuestionLabels = {
  activity: "Numeric question",
  promptPending: "The question is still loading.",
  response: "Your answer",
  responsePlaceholder: "Enter a number",
  displayUnit: (unit) => `Answers are measured in ${unit}.`,
  requiredUnit: (unit) => `Include the unit ${unit}.`,
  submit: "Check answer",
  correct: "Correct",
  incorrect: "Needs revision",
  ungraded: "Response submitted",
  invalidNumber: "Enter a valid number.",
  unitMismatch: (unit) => `Use the required unit ${unit}.`,
  expectedValue: (value) => `Expected value: ${value}`,
  expectedRange: (range) => `Accepted range: ${range}`,
};

export interface NumericQuestionInputContext {
  id: string;
  value: string;
  disabled: boolean;
  describedBy?: string;
  invalid: boolean;
  placeholder: string;
  onChange: (value: string) => void;
}

export interface NumericQuestionProps
  extends Omit<
    React.ComponentPropsWithoutRef<"section">,
    "children" | "defaultValue" | "onSubmit" | "title"
  > {
  prompt?: React.ReactNode;
  description?: React.ReactNode;
  rule?: NumericQuestionRule;
  unit?: NumericQuestionUnit;
  numberFormat?: NumericQuestionNumberFormat;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  submitted?: boolean;
  defaultSubmitted?: boolean;
  onSubmittedChange?: (submitted: boolean) => void;
  onSubmit?: (result: NumericQuestionResult) => void;
  disabled?: boolean;
  labels?: Partial<NumericQuestionLabels>;
  feedback?: Partial<Record<NumericQuestionStatus, React.ReactNode>>;
  formatValue?: (value: number) => string;
  renderInput?: (context: NumericQuestionInputContext) => React.ReactNode;
  renderFeedback?: (result: NumericQuestionResult) => React.ReactNode;
}

interface ParsedNumber {
  value: number | null;
  reason?: "invalid-number" | "unit-mismatch";
}

function parseNumber(
  rawValue: string,
  format: NumericQuestionNumberFormat,
  unit?: NumericQuestionUnit,
): ParsedNumber {
  let candidate = rawValue.trim().normalize("NFKC").replace(/[\u2212\u2012-\u2014]/g, "-");

  if (unit?.policy === "required") {
    const aliases = [unit.symbol, ...(unit.aliases ?? [])]
      .map((alias) => alias.trim())
      .filter(Boolean)
      .sort((a, b) => b.length - a.length);
    const comparable = unit.caseSensitive ? candidate : candidate.toLocaleLowerCase();
    const matchedUnit = aliases.find((alias) => {
      const comparableAlias = unit.caseSensitive ? alias : alias.toLocaleLowerCase();
      return comparable.endsWith(comparableAlias);
    });
    if (!matchedUnit) return { value: null, reason: "unit-mismatch" };
    candidate = candidate.slice(0, -matchedUnit.length).trim();
  }

  const separator = format.decimalSeparator ?? ".";
  if (separator === ",") candidate = candidate.replace(",", ".");
  const exponent = format.allowExponent === false ? "" : "(?:[eE][+-]?\\d+)?";
  const pattern = new RegExp(`^[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)${exponent}$`);
  if (!pattern.test(candidate)) return { value: null, reason: "invalid-number" };
  const value = Number(candidate);
  return Number.isFinite(value)
    ? { value }
    : { value: null, reason: "invalid-number" };
}

function isValidRule(rule: NumericQuestionRule): boolean {
  if (rule.kind === "value") return Number.isFinite(rule.value);
  return (rule.min === undefined || Number.isFinite(rule.min))
    && (rule.max === undefined || Number.isFinite(rule.max))
    && (rule.min !== undefined || rule.max !== undefined);
}

function evaluate(
  rawValue: string,
  rule: NumericQuestionRule | undefined,
  format: NumericQuestionNumberFormat,
  unit?: NumericQuestionUnit,
): NumericQuestionResult {
  const parsed = parseNumber(rawValue, format, unit);
  const base = {
    rawValue,
    value: parsed.value,
    ...(unit ? { unit: unit.symbol } : {}),
  };
  if (!rule || !isValidRule(rule)) {
    return { ...base, status: "ungraded", reason: parsed.reason ?? "ungraded" };
  }
  if (parsed.value === null) {
    return { ...base, status: "incorrect", reason: parsed.reason ?? "invalid-number" };
  }

  if (rule.kind === "range") {
    const aboveMinimum = rule.min === undefined
      || (rule.includeMin === false ? parsed.value > rule.min : parsed.value >= rule.min);
    const belowMaximum = rule.max === undefined
      || (rule.includeMax === false ? parsed.value < rule.max : parsed.value <= rule.max);
    return aboveMinimum && belowMaximum
      ? { ...base, status: "correct", reason: "matched" }
      : { ...base, status: "incorrect", reason: "outside-range" };
  }

  const difference = Math.abs(parsed.value - rule.value);
  const tolerance = rule.tolerance;
  if (!tolerance || (tolerance.absolute === undefined && tolerance.relative === undefined)) {
    return difference === 0
      ? { ...base, status: "correct", reason: "matched" }
      : { ...base, status: "incorrect", reason: "outside-tolerance" };
  }
  const checks: boolean[] = [];
  if (tolerance.absolute !== undefined) checks.push(difference <= Math.max(0, tolerance.absolute));
  if (tolerance.relative !== undefined) {
    checks.push(difference <= Math.abs(rule.value) * Math.max(0, tolerance.relative));
  }
  const matches = tolerance.mode === "both" ? checks.every(Boolean) : checks.some(Boolean);
  return matches
    ? { ...base, status: "correct", reason: "matched" }
    : { ...base, status: "incorrect", reason: "outside-tolerance" };
}

function describeRule(
  rule: NumericQuestionRule,
  unit: NumericQuestionUnit | undefined,
  formatValue: (value: number) => string,
): { kind: "value" | "range"; text: string } {
  const suffix = unit ? ` ${unit.symbol}` : "";
  if (rule.kind === "value") {
    return { kind: "value", text: `${formatValue(rule.value)}${suffix}` };
  }
  const left = rule.min === undefined
    ? "−∞"
    : `${rule.includeMin === false ? "(" : "["}${formatValue(rule.min)}`;
  const right = rule.max === undefined
    ? "+∞"
    : `${formatValue(rule.max)}${rule.includeMax === false ? ")" : "]"}`;
  return { kind: "range", text: `${left}, ${right}${suffix}` };
}

/**
 * A quantitative response with explicit grading, tolerance and unit semantics. The grading rule
 * and accepted answer remain absent from the DOM until submission.
 */
export const NumericQuestion = React.forwardRef<HTMLElement, NumericQuestionProps>(
  function NumericQuestion(
    {
      prompt,
      description,
      rule,
      unit,
      numberFormat = {},
      value: valueProp,
      defaultValue = "",
      onValueChange,
      submitted: submittedProp,
      defaultSubmitted = false,
      onSubmittedChange,
      onSubmit,
      disabled = false,
      labels,
      feedback,
      formatValue = String,
      renderInput,
      renderFeedback,
      className,
      "aria-label": ariaLabel,
      "aria-labelledby": ariaLabelledby,
      ...props
    },
    ref,
  ) {
    const copy = { ...defaultLabels, ...labels };
    const titleId = React.useId();
    const inputId = React.useId();
    const helpId = React.useId();
    const resultId = React.useId();
    const [value, setValue] = useControllable(valueProp, defaultValue, onValueChange);
    const [submitted, setSubmitted] = useControllable(
      submittedProp,
      defaultSubmitted,
      onSubmittedChange,
    );
    const result = submitted ? evaluate(value, rule, numberFormat, unit) : undefined;
    const canSubmit = value.trim().length > 0 && !disabled && !submitted;
    const invalid = result?.reason === "invalid-number" || result?.reason === "unit-mismatch";
    const describedBy = [unit ? helpId : undefined, result ? resultId : undefined]
      .filter(Boolean)
      .join(" ") || undefined;

    const submit = (event: React.FormEvent) => {
      event.preventDefault();
      if (!canSubmit) return;
      const nextResult = evaluate(value, rule, numberFormat, unit);
      setSubmitted(true);
      onSubmit?.(nextResult);
    };

    const inputContext: NumericQuestionInputContext = {
      id: inputId,
      value,
      disabled: disabled || submitted,
      describedBy,
      invalid,
      placeholder: copy.responsePlaceholder,
      onChange: setValue,
    };

    return (
      <section
        ref={ref}
        data-slot="numeric-question"
        data-status={result?.status}
        aria-label={ariaLabel ?? (ariaLabelledby === undefined && prompt === undefined ? copy.activity : undefined)}
        aria-labelledby={ariaLabelledby ?? (prompt !== undefined ? titleId : undefined)}
        className={cn("w-full max-w-2xl", className)}
        {...props}
      >
        <Card>
          <CardHeader>
            <CardTitle id={titleId}>{prompt ?? copy.promptPending}</CardTitle>
            {description !== undefined ? <CardDescription>{description}</CardDescription> : null}
          </CardHeader>
          <form onSubmit={submit} className="flex flex-col gap-6">
            <CardContent className="flex flex-col gap-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor={inputId}>{copy.response}</Label>
                <div className="flex items-center gap-3">
                  <div className="min-w-0 flex-1">
                    {renderInput ? renderInput(inputContext) : (
                      <Input
                        id={inputId}
                        type="text"
                        inputMode="decimal"
                        autoComplete="off"
                        value={value}
                        placeholder={copy.responsePlaceholder}
                        disabled={disabled || submitted}
                        aria-describedby={describedBy}
                        aria-invalid={invalid || undefined}
                        onChange={(event) => setValue(event.target.value)}
                      />
                    )}
                  </div>
                  {unit?.policy === "display" ? (
                    <span className="shrink-0 text-sm font-medium text-foreground" aria-hidden="true">
                      {unit.symbol}
                    </span>
                  ) : null}
                </div>
                {unit ? (
                  <p
                    id={helpId}
                    className={unit.policy === "display" ? "sr-only" : "text-sm text-muted-foreground"}
                  >
                    {unit.policy === "display"
                      ? copy.displayUnit(unit.symbol)
                      : copy.requiredUnit(unit.symbol)}
                  </p>
                ) : null}
              </div>

              {result ? (
                <div id={resultId} role="status" aria-live="polite" className="rounded-md border bg-muted p-4 text-sm">
                  <p className="font-medium text-foreground">
                    {result.status === "correct"
                      ? copy.correct
                      : result.status === "incorrect"
                        ? copy.incorrect
                        : copy.ungraded}
                  </p>
                  {result.reason === "invalid-number" ? (
                    <p className="mt-1 text-muted-foreground">{copy.invalidNumber}</p>
                  ) : null}
                  {result.reason === "unit-mismatch" && unit ? (
                    <p className="mt-1 text-muted-foreground">{copy.unitMismatch(unit.symbol)}</p>
                  ) : null}
                  {result.status === "incorrect" && result.value !== null && rule && isValidRule(rule) ? (() => {
                    const expectation = describeRule(rule, unit, formatValue);
                    return (
                      <p className="mt-1 text-muted-foreground">
                        {expectation.kind === "value"
                          ? copy.expectedValue(expectation.text)
                          : copy.expectedRange(expectation.text)}
                      </p>
                    );
                  })() : null}
                  {feedback?.[result.status] !== undefined ? (
                    <div className="mt-2 text-muted-foreground">{feedback[result.status]}</div>
                  ) : null}
                  {renderFeedback ? (
                    <div className="mt-2 text-muted-foreground">{renderFeedback(result)}</div>
                  ) : null}
                </div>
              ) : null}
            </CardContent>
            {!submitted ? (
              <CardFooter>
                <Button type="submit" disabled={!canSubmit}>{copy.submit}</Button>
              </CardFooter>
            ) : null}
          </form>
        </Card>
      </section>
    );
  },
);

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

