}

function DroppableGapButton({
  gapId,
  disabled,
  selected,
  assigned,
  invalid,
  describedBy,
  label,
  onClick,
  children,
}: DroppableGapButtonProps) {
  const { setNodeRef, isOver } = useDroppable({
    id: `word-bank-gap:${gapId}`,
    data: { kind: "word-bank-gap", gapId } satisfies WordBankDropData,
