const IDENTIFIER = /^[a-z0-9]+(?:[.-][a-z0-9]+)*$/;

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function localizedText(value: unknown): boolean {
  if (typeof value === "string") return value.trim().length > 0;
  return record(value)
    && Object.keys(value).length > 0
    && Object.values(value).every((entry) => typeof entry === "string" && entry.trim().length > 0);
}

function add(issues: ValidationIssue[], path: string, code: string, message: string): void {
  issues.push({ path, code, message, severity: "error" });
}

function validIdentifier(value: unknown): value is string {
  return typeof value === "string" && IDENTIFIER.test(value);
}

function validSerializable(value: unknown, seen = new Set<unknown>()): boolean {
  if (value === null || typeof value === "string" || typeof value === "boolean") return true;
  if (typeof value === "number") return Number.isFinite(value);
  if (typeof value !== "object") return false;
  if (seen.has(value)) return false;
  seen.add(value);
  const valid = Array.isArray(value)
    ? value.every((entry) => validSerializable(entry, seen))
    : Object.getPrototypeOf(value) === Object.prototype
      && Object.values(value as Record<string, unknown>).every((entry) => validSerializable(entry, seen));
  seen.delete(value);
  return valid;
}

export function validateInteractiveMediaDefinition(
  input: unknown,
  options: InteractiveMediaValidationOptions = {},
): ValidationResult<InteractiveMediaDefinition> {
  const issues: ValidationIssue[] = [];
  const complete = (options.mode ?? "complete") === "complete";
  if (!record(input)) {
    add(issues, "$", "interactive-media.object", "Interactive media must be an object.");
    return { success: false, issues };
  }

  if (input.schemaVersion !== INTERACTIVE_MEDIA_SCHEMA_VERSION) add(issues, "schemaVersion", "interactive-media.version", `schemaVersion must be ${INTERACTIVE_MEDIA_SCHEMA_VERSION}.`);
  if (!validIdentifier(input.id)) add(issues, "id", "interactive-media.id", "id must be a stable lowercase identifier.");
  if (!localizedText(input.title) && complete) add(issues, "title", "interactive-media.title", "title is required.");
  if (input.learningObjective !== undefined && !localizedText(input.learningObjective)) add(issues, "learningObjective", "interactive-media.learning-objective", "learningObjective must be localized text.");

  const media = input.media;
  if (!record(media)) add(issues, "media", "interactive-media.media", "media is required.");
  else {
    if (media.kind !== "audio" && media.kind !== "video") add(issues, "media.kind", "interactive-media.media-kind", "media.kind must be audio or video.");
    if ((typeof media.src !== "string" || media.src.trim().length === 0) && complete) add(issues, "media.src", "interactive-media.media-src", "media.src is required.");
    if (media.durationMs !== undefined && (typeof media.durationMs !== "number" || !Number.isFinite(media.durationMs) || media.durationMs <= 0)) add(issues, "media.durationMs", "interactive-media.duration", "durationMs must be a positive finite number.");

    const tracks = Array.isArray(media.tracks) ? media.tracks : [];
    const trackIds = new Set<string>();
    for (const [index, track] of tracks.entries()) {
      const path = `media.tracks[${index}]`;
      if (!record(track)) { add(issues, path, "interactive-media.track", "Track must be an object."); continue; }
      if (!validIdentifier(track.id)) add(issues, `${path}.id`, "interactive-media.track-id", "Track id must be stable.");
      else if (trackIds.has(track.id)) add(issues, `${path}.id`, "interactive-media.track-duplicate", "Track ids must be unique.");
      else trackIds.add(track.id);
      if (!["captions", "subtitles", "descriptions"].includes(String(track.kind))) add(issues, `${path}.kind`, "interactive-media.track-kind", "Unknown track kind.");
      if (typeof track.src !== "string" || track.src.trim().length === 0) add(issues, `${path}.src`, "interactive-media.track-src", "Track src is required.");
      if (!localizedText(track.label)) add(issues, `${path}.label`, "interactive-media.track-label", "Track label is required.");
      if ((track.kind === "captions" || track.kind === "subtitles") && (typeof track.language !== "string" || track.language.trim().length === 0)) add(issues, `${path}.language`, "interactive-media.track-language", "Caption and subtitle tracks require a language.");
    }

    const transcript = Array.isArray(media.transcript) ? media.transcript : [];
    const cueIds = new Set<string>();
    let previousStart = -1;
    for (const [index, cue] of transcript.entries()) {
      const path = `media.transcript[${index}]`;
      if (!record(cue)) { add(issues, path, "interactive-media.cue", "Transcript cue must be an object."); continue; }
      if (!validIdentifier(cue.id)) add(issues, `${path}.id`, "interactive-media.cue-id", "Cue id must be stable.");
      else if (cueIds.has(cue.id)) add(issues, `${path}.id`, "interactive-media.cue-duplicate", "Cue ids must be unique.");
      else cueIds.add(cue.id);
      if (typeof cue.startMs !== "number" || !Number.isFinite(cue.startMs) || cue.startMs < 0) add(issues, `${path}.startMs`, "interactive-media.cue-start", "startMs must be zero or greater.");
      if (typeof cue.endMs !== "number" || !Number.isFinite(cue.endMs) || cue.endMs <= Number(cue.startMs)) add(issues, `${path}.endMs`, "interactive-media.cue-end", "endMs must be greater than startMs.");
      if (typeof cue.startMs === "number" && cue.startMs < previousStart) add(issues, path, "interactive-media.cue-order", "Transcript cues must be ordered by startMs.");
      previousStart = typeof cue.startMs === "number" ? cue.startMs : previousStart;
      if (typeof media.durationMs === "number" && typeof cue.endMs === "number" && cue.endMs > media.durationMs) add(issues, `${path}.endMs`, "interactive-media.cue-bounds", "Transcript cue exceeds media duration.");
      if (!localizedText(cue.text)) add(issues, `${path}.text`, "interactive-media.cue-text", "Transcript cue text is required.");
    }

    if (complete && media.kind === "audio" && transcript.length === 0) add(issues, "media.transcript", "interactive-media.audio-transcript", "Prerecorded audio requires a transcript.");
    if (complete && media.kind === "video" && media.noSpeech !== true && !tracks.some((track) => record(track) && track.kind === "captions")) add(issues, "media.tracks", "interactive-media.video-captions", "Video with speech requires a captions track.");
    if (complete && media.kind === "video" && media.visualContentIsDecorative !== true && !localizedText(media.visualDescription) && !tracks.some((track) => record(track) && track.kind === "descriptions")) add(issues, "media.visualDescription", "interactive-media.video-description", "Meaningful video requires a visual description or descriptions track.");
  }

  const checkpoints = input.checkpoints;
  if (!Array.isArray(checkpoints)) add(issues, "checkpoints", "interactive-media.checkpoints", "checkpoints must be a list.");
  else {
    if (complete && checkpoints.length === 0) add(issues, "checkpoints", "interactive-media.checkpoints-empty", "Interactive media requires at least one checkpoint.");
    const ids = new Set<string>();
    let previousAt = -1;
    for (const [index, checkpoint] of checkpoints.entries()) {
      const path = `checkpoints[${index}]`;
      if (!record(checkpoint)) { add(issues, path, "interactive-media.checkpoint", "Checkpoint must be an object."); continue; }
      if (!validIdentifier(checkpoint.id)) add(issues, `${path}.id`, "interactive-media.checkpoint-id", "Checkpoint id must be stable.");
      else if (ids.has(checkpoint.id)) add(issues, `${path}.id`, "interactive-media.checkpoint-duplicate", "Checkpoint ids must be unique.");
      else ids.add(checkpoint.id);
      if (typeof checkpoint.atMs !== "number" || !Number.isFinite(checkpoint.atMs) || checkpoint.atMs < 0) add(issues, `${path}.atMs`, "interactive-media.checkpoint-time", "atMs must be zero or greater.");
      if (typeof checkpoint.atMs === "number" && checkpoint.atMs < previousAt) add(issues, path, "interactive-media.checkpoint-order", "Checkpoints must be ordered by atMs.");
      previousAt = typeof checkpoint.atMs === "number" ? checkpoint.atMs : previousAt;
      if (record(media) && typeof media.durationMs === "number" && typeof checkpoint.atMs === "number" && checkpoint.atMs > media.durationMs) add(issues, `${path}.atMs`, "interactive-media.checkpoint-bounds", "Checkpoint exceeds media duration.");
      if (!record(checkpoint.activity)) add(issues, `${path}.activity`, "interactive-media.activity", "Checkpoint activity is required.");
      else {
        if (!validIdentifier(checkpoint.activity.id)) add(issues, `${path}.activity.id`, "interactive-media.activity-id", "Activity id must be stable.");
        if (!validIdentifier(checkpoint.activity.manifestId)) add(issues, `${path}.activity.manifestId`, "interactive-media.manifest-id", "manifestId must be stable.");
        if (checkpoint.activity.typeId !== undefined && !validIdentifier(checkpoint.activity.typeId)) add(issues, `${path}.activity.typeId`, "interactive-media.type-id", "typeId must be stable.");
        if (!record(checkpoint.activity.authoring) || !validSerializable(checkpoint.activity.authoring)) add(issues, `${path}.activity.authoring`, "interactive-media.authoring", "Child authoring data must be a JSON-safe object.");
      }
    }
  }

  if (!record(input.completion)) add(issues, "completion", "interactive-media.completion", "completion policy is required.");
  else {
    if (!["media-ended", "required-checkpoints", "both"].includes(String(input.completion.kind))) add(issues, "completion.kind", "interactive-media.completion-kind", "Unknown completion policy.");
    if (input.completion.minimumWatchRatio !== undefined && (typeof input.completion.minimumWatchRatio !== "number" || input.completion.minimumWatchRatio < 0 || input.completion.minimumWatchRatio > 1)) add(issues, "completion.minimumWatchRatio", "interactive-media.watch-ratio", "minimumWatchRatio must be between 0 and 1.");
  }

  return issues.length > 0
    ? { success: false, issues }
    : { success: true, data: input as unknown as InteractiveMediaDefinition, issues };
}

import * as React from "react";
import { MdForward10, MdPause, MdPlayArrow } from "react-icons/md";
import { Button } from "@/components/ui/button";

import { cn } from "@/lib/didact/cn";

export interface MediaPlayerTrack {
  id: string;
  kind: "captions" | "subtitles" | "descriptions";
  src: string;
  language?: string;
  label: string;
  default?: boolean;
}

export interface MediaPlayerController {
  play: () => void | Promise<void>;
  pause: () => void;
  seek: (positionMs: number) => void;
}

export interface MediaPlayerLabels {
  play: string;
  pause: string;
  seek: string;
  forwardTen: string;
}

const defaultLabels: MediaPlayerLabels = {
  play: "Play",
  pause: "Pause",
  seek: "Media position",
  forwardTen: "Advance 10 seconds",
};

export interface MediaPlayerProps extends Omit<React.ComponentPropsWithoutRef<"div">, "children" | "onTimeUpdate"> {
  kind: "audio" | "video";
  src: string;
  poster?: string;
  tracks?: readonly MediaPlayerTrack[];
  durationMs?: number;
  disabled?: boolean;
  labels?: Partial<MediaPlayerLabels>;
  onTimeChange?: (positionMs: number, durationMs?: number) => void;
  onPlay?: () => void;
  onPause?: () => void;
  onEnded?: () => void;
  onControllerChange?: (controller: MediaPlayerController | null) => void;
}

function formatTime(milliseconds: number) {
  const total = Math.max(0, Math.floor(milliseconds / 1_000));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
}

export function MediaPlayer({
  kind,
  src,
  poster,
  tracks,
  durationMs: durationFallback,
  disabled = false,
  labels: labelOverrides,
  onTimeChange,
  onPlay,
  onPause,
  onEnded,
  onControllerChange,
  className,
  ...props
}: MediaPlayerProps) {
  const labels = { ...defaultLabels, ...labelOverrides };
  const mediaRef = React.useRef<HTMLMediaElement | null>(null);
  const [playing, setPlaying] = React.useState(false);
  const [positionMs, setPositionMs] = React.useState(0);
  const [durationMs, setDurationMs] = React.useState(durationFallback ?? 0);

  const seek = React.useCallback((nextPositionMs: number) => {
    const duration = durationMs || durationFallback || nextPositionMs;
    const next = Math.max(0, Math.min(duration, nextPositionMs));
    if (mediaRef.current) mediaRef.current.currentTime = next / 1_000;
    setPositionMs(next);
    onTimeChange?.(next, duration || undefined);
  }, [durationFallback, durationMs, onTimeChange]);

  const play = React.useCallback(async () => {
    if (disabled) return;
    await mediaRef.current?.play();
  }, [disabled]);
  const pause = React.useCallback(() => mediaRef.current?.pause(), []);

  React.useEffect(() => {
    onControllerChange?.({ play, pause, seek });
    return () => onControllerChange?.(null);
  }, [onControllerChange, pause, play, seek]);

  const updateFromElement = (element: HTMLMediaElement) => {
    const nextDuration = Number.isFinite(element.duration) ? element.duration * 1_000 : durationFallback;
    if (nextDuration) setDurationMs(nextDuration);
    const nextPosition = element.currentTime * 1_000;
    setPositionMs(nextPosition);
    onTimeChange?.(nextPosition, nextDuration);
  };

  const mediaProps = {
    ref: (node: HTMLMediaElement | null) => { mediaRef.current = node; },
    src,
    preload: "metadata" as const,
    tabIndex: -1,
    onLoadedMetadata: (event: React.SyntheticEvent<HTMLMediaElement>) => updateFromElement(event.currentTarget),
    onTimeUpdate: (event: React.SyntheticEvent<HTMLMediaElement>) => updateFromElement(event.currentTarget),
    onPlay: () => { setPlaying(true); onPlay?.(); },
    onPause: () => { setPlaying(false); onPause?.(); },
    onEnded: () => { setPlaying(false); onEnded?.(); },
  };
  const trackNodes = tracks?.map((track) => <track key={track.id} kind={track.kind} src={track.src} srcLang={track.language} label={track.label} default={track.default} />);
  const controls = <div className={cn("flex items-center gap-2 px-3 py-3 sm:gap-3 sm:px-4", kind === "video" && "absolute inset-x-0 bottom-0 text-background")}>
    <Button type="button" variant="ghost" size="icon-sm" disabled={disabled} onClick={() => { if (playing) pause(); else void play(); }} aria-label={playing ? labels.pause : labels.play} title={playing ? labels.pause : labels.play} className={cn("shrink-0 hover:bg-transparent", kind === "video" && "text-background hover:text-background")}>
      {playing ? <MdPause className="size-5" aria-hidden="true" /> : <MdPlayArrow className="size-5" aria-hidden="true" />}
    </Button>
    <label className="flex min-w-0 flex-1 items-center gap-2">
      <span className={cn("shrink-0 text-xs tabular-nums text-muted-foreground", kind === "video" && "text-background")}>{formatTime(positionMs)}</span>
      <input aria-label={labels.seek} type="range" min={0} max={durationMs || durationFallback || 0} step={1_000} value={positionMs} disabled={disabled || !(durationMs || durationFallback)} onChange={(event) => seek(Number(event.currentTarget.value))} className={cn("min-w-0 flex-1 accent-foreground", kind === "video" && "accent-background")} />
      <span className={cn("shrink-0 text-xs tabular-nums text-muted-foreground", kind === "video" && "text-background")}>{formatTime(durationMs || durationFallback || 0)}</span>
    </label>
    <Button type="button" variant="ghost" size="icon-sm" disabled={disabled} onClick={() => seek(positionMs + 10_000)} aria-label={labels.forwardTen} title={labels.forwardTen} className={cn("shrink-0 hover:bg-transparent", kind === "video" && "text-background hover:text-background")}><MdForward10 className="size-5" aria-hidden="true" /></Button>
  </div>;

  return <div data-slot="media-player" data-kind={kind} className={cn("bg-background", kind === "video" && "relative overflow-hidden bg-foreground", className)} {...props}>
    {kind === "video" ? <video {...mediaProps} poster={poster} className="aspect-video w-full object-contain">{trackNodes}</video> : <audio {...mediaProps}>{trackNodes}</audio>}
    {controls}
  </div>;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

import * as React from "react";
import { MdCheck, MdClose } from "react-icons/md";
import { validateInteractiveMediaDefinition, type EmbeddedLearningActivity, type InteractiveMediaDefinition, type InteractiveMediaRuntimeState } from "@/lib/didact/schema/interactive-media";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";

import { cn } from "@/lib/didact/cn";
import { MediaPlayer } from "./media-player.js";

export interface InteractiveMediaPlayerController {
  play: () => void | Promise<void>;
  pause: () => void;
  seek: (positionMs: number) => void;
}

export interface InteractiveMediaPlayerContext {
  definition: InteractiveMediaDefinition;
  disabled: boolean;
  setController: (controller: InteractiveMediaPlayerController | null) => void;
  onTimeChange: (positionMs: number, durationMs?: number) => void;
  onPlay: () => void;
  onPause: () => void;
  onEnded: () => void;
}

export interface InteractiveMediaActivityContext {
  checkpointId: string;
  completed: boolean;
  disabled: boolean;
  complete: () => void;
  close: () => void;
}

export interface InteractiveMediaLabels {
  loading: string;
  invalid: string;
  checkpoints: string;
  transcript: string;
  openCheckpoint: (label: string) => string;
  completed: string;
  optional: string;
  required: string;
  close: string;
  markComplete: string;
  progress: (completed: number, total: number) => string;
  position: (position: string, duration?: string) => string;
}

const defaultLabels: InteractiveMediaLabels = {
  loading: "Media is still loading.",
  invalid: "This interactive media configuration is incomplete.",
  checkpoints: "Learning checkpoints",
  transcript: "Transcript",
  openCheckpoint: (label) => `Open checkpoint: ${label}`,
  completed: "Completed",
  optional: "Optional",
  required: "Required",
  close: "Close checkpoint",
  markComplete: "Mark checkpoint complete",
  progress: (completed, total) => `${completed} of ${total} required checkpoints completed`,
  position: (position, duration) => duration ? `${position} of ${duration}` : position,
};

const initialState: InteractiveMediaRuntimeState = {
  status: "idle",
  positionMs: 0,
  watchedMs: 0,
  mediaEnded: false,
  completedCheckpointIds: [],
};

function localText(value: string | Record<string, string> | undefined): string | undefined {
  if (typeof value === "string") return value;
  return value?.en ?? (value ? Object.values(value)[0] : undefined);
}

function formatTime(milliseconds: number): string {
  const total = Math.max(0, Math.floor(milliseconds / 1000));
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
}

function completionSatisfied(definition: InteractiveMediaDefinition, state: InteractiveMediaRuntimeState): boolean {
  const required = definition.checkpoints.filter(({ required }) => required !== false).map(({ id }) => id);
  const checkpointsComplete = required.every((id) => state.completedCheckpointIds.includes(id));
  const ratio = definition.completion.minimumWatchRatio;
  const duration = state.durationMs ?? definition.media.durationMs;
  const watchComplete = ratio === undefined || (duration !== undefined && state.watchedMs / duration >= ratio);
  const policyComplete = definition.completion.kind === "media-ended"
    ? state.mediaEnded
    : definition.completion.kind === "required-checkpoints"
      ? checkpointsComplete
      : state.mediaEnded && checkpointsComplete;
  return policyComplete && watchComplete;
}

function NativeMediaPlayer({ context }: { context: InteractiveMediaPlayerContext }) {
  const { definition, disabled, setController, onTimeChange, onPlay, onPause, onEnded } = context;
  return <MediaPlayer
    kind={definition.media.kind}
    src={definition.media.src}
    poster={definition.media.poster}
    durationMs={definition.media.durationMs}
    tracks={definition.media.tracks?.map((track) => ({ ...track, label: localText(track.label) ?? track.id }))}
    disabled={disabled}
    onControllerChange={setController}
    onTimeChange={onTimeChange}
    onPlay={onPlay}
    onPause={onPause}
    onEnded={onEnded}
  />;
}

export interface InteractiveMediaProps extends Omit<React.ComponentPropsWithoutRef<"section">, "children" | "title" | "onChange"> {
  definition?: InteractiveMediaDefinition;
  validationMode?: "complete" | "streaming";
  state?: InteractiveMediaRuntimeState;
  defaultState?: Partial<InteractiveMediaRuntimeState>;
  onStateChange?: (state: InteractiveMediaRuntimeState) => void;
  onCheckpointOpen?: (checkpointId: string) => void;
  onCheckpointComplete?: (checkpointId: string) => void;
  onComplete?: (state: InteractiveMediaRuntimeState) => void;
  renderActivity: (activity: EmbeddedLearningActivity, context: InteractiveMediaActivityContext) => React.ReactNode;
  renderPlayer?: (context: InteractiveMediaPlayerContext) => React.ReactNode;
  disabled?: boolean;
  labels?: Partial<InteractiveMediaLabels>;
}

export function InteractiveMedia({
  definition,
  validationMode = "complete",
  state: stateProp,
  defaultState,
  onStateChange,
  onCheckpointOpen,
  onCheckpointComplete,
  onComplete,
  renderActivity,
  renderPlayer,
  disabled = false,
  labels: labelOverrides,
  className,
  ...props
}: InteractiveMediaProps) {
  const labels = { ...defaultLabels, ...labelOverrides };
  const controlled = stateProp !== undefined;
  const [localState, setLocalState] = React.useState<InteractiveMediaRuntimeState>({ ...initialState, ...defaultState });
  const state = stateProp ?? localState;
  const controllerRef = React.useRef<InteractiveMediaPlayerController | null>(null);
  const encounteredRef = React.useRef(new Set<string>());
  const completionEmittedRef = React.useRef(false);
  const validation = React.useMemo(() => validateInteractiveMediaDefinition(definition, { mode: validationMode }), [definition, validationMode]);

  const commit = React.useCallback((next: InteractiveMediaRuntimeState) => {
    const completed = definition && completionSatisfied(definition, next) ? { ...next, status: "completed" as const } : next;
    if (!controlled) setLocalState(completed);
    onStateChange?.(completed);
    if (completed.status === "completed" && !completionEmittedRef.current) {
      completionEmittedRef.current = true;
      onComplete?.(completed);
    }
  }, [controlled, definition, onComplete, onStateChange]);

  if (!definition || (validationMode === "streaming" && !validation.success)) {
    return <Card className={cn("w-full max-w-5xl gap-0 overflow-hidden py-0", className)} data-slot="interactive-media" data-state="loading" {...props}>
      <CardContent className="grid min-h-40 place-items-center p-6 text-center" role="status">
        <div className="grid max-w-sm gap-3">
          <span className="mx-auto size-8 rounded-full border-2 border-muted border-t-primary motion-safe:animate-spin" aria-hidden="true" />
          <p className="text-sm text-muted-foreground">{labels.loading}</p>
        </div>
      </CardContent>
    </Card>;
  }
  if (!validation.success) {
    return <Card className={cn("w-full max-w-5xl gap-0 overflow-hidden py-0", className)} data-slot="interactive-media" data-state="invalid" {...props}>
      <CardContent className="p-5 sm:p-6" role="alert">
        <p className="font-semibold">{labels.invalid}</p>
        <ul className="mt-2 list-disc pl-5 text-sm leading-6 text-muted-foreground">{validation.issues.map((issue) => <li key={`${issue.path}:${issue.code}`}>{issue.message}</li>)}</ul>
      </CardContent>
    </Card>;
  }

  const required = definition.checkpoints.filter(({ required: isRequired }) => isRequired !== false);
  const completedRequired = required.filter(({ id }) => state.completedCheckpointIds.includes(id)).length;
  const active = definition.checkpoints.find(({ id }) => id === state.activeCheckpointId);
  const duration = state.durationMs ?? definition.media.durationMs;
  const setController = React.useCallback((controller: InteractiveMediaPlayerController | null) => { controllerRef.current = controller; }, []);
  const openCheckpoint = (checkpointId: string) => {
    if (disabled) return;
    const checkpoint = definition.checkpoints.find(({ id }) => id === checkpointId);
    if (!checkpoint) return;
    encounteredRef.current.add(checkpoint.id);
    if (checkpoint.pause !== false) controllerRef.current?.pause();
    commit({ ...state, status: "paused", activeCheckpointId: checkpoint.id });
    onCheckpointOpen?.(checkpoint.id);
  };
  const onTimeChange = (positionMs: number, durationMs?: number) => {
    const delta = state.status === "playing" && positionMs >= state.positionMs && positionMs - state.positionMs <= 2_000 ? positionMs - state.positionMs : 0;
    const next = { ...state, positionMs, durationMs: durationMs ?? state.durationMs, watchedMs: Math.min(durationMs ?? definition.media.durationMs ?? Number.POSITIVE_INFINITY, state.watchedMs + delta) };
    const crossed = definition.checkpoints.find((checkpoint) => !encounteredRef.current.has(checkpoint.id) && checkpoint.atMs <= positionMs && (checkpoint.atMs > state.positionMs || (state.positionMs === 0 && checkpoint.atMs === 0)));
    if (crossed) {
      encounteredRef.current.add(crossed.id);
      if (crossed.pause !== false) controllerRef.current?.pause();
      commit({ ...next, status: "paused", activeCheckpointId: crossed.id });
      onCheckpointOpen?.(crossed.id);
    } else commit(next);
  };
  const markComplete = (checkpointId: string) => {
    if (disabled || state.completedCheckpointIds.includes(checkpointId)) return;
    const next = { ...state, activeCheckpointId: undefined, completedCheckpointIds: [...state.completedCheckpointIds, checkpointId] };
    commit(next);
    onCheckpointComplete?.(checkpointId);
  };
  const playerContext: InteractiveMediaPlayerContext = {
    definition,
    disabled,
    setController,
    onTimeChange,
    onPlay: () => { if (!disabled) commit({ ...state, status: "playing" }); },
    onPause: () => { if (state.status !== "completed") commit({ ...state, status: "paused" }); },
    onEnded: () => commit({ ...state, positionMs: duration ?? state.positionMs, mediaEnded: true, status: "paused" }),
  };

  return <section className={cn("w-full max-w-5xl", className)} data-slot="interactive-media" data-state={state.status} aria-disabled={disabled || undefined} {...props}>
    <Card className="gap-0 overflow-hidden py-0">
      <CardHeader className="gap-2 px-5 py-5 sm:px-6">
        <CardTitle role="heading" aria-level={2} className="text-balance text-lg leading-tight sm:text-xl">{localText(definition.title)}</CardTitle>
        {definition.learningObjective ? <p className="max-w-3xl text-sm leading-6 text-muted-foreground">{localText(definition.learningObjective)}</p> : null}
      </CardHeader>

      <div className="border-y bg-background">
        {renderPlayer ? renderPlayer(playerContext) : <NativeMediaPlayer context={playerContext} />}
      </div>
      {definition.media.visualDescription ? <p className="border-b px-5 py-3 text-sm leading-6 text-muted-foreground sm:px-6">{localText(definition.media.visualDescription)}</p> : null}

      <CardContent className="grid gap-4 px-5 py-4 sm:px-6">
        {definition.checkpoints.length ? <div className="grid gap-3">
          <div>
            <h3 className="text-sm font-semibold">{labels.checkpoints}</h3>
            <p className="mt-0.5 text-xs text-muted-foreground">{labels.progress(completedRequired, required.length)}</p>
          </div>
          <ol className="grid gap-1">
            {definition.checkpoints.map((checkpoint) => {
              const checkpointLabel = localText(checkpoint.label) ?? formatTime(checkpoint.atMs);
              const complete = state.completedCheckpointIds.includes(checkpoint.id);
              const status = complete ? labels.completed : checkpoint.required === false ? labels.optional : labels.required;
              return <li key={checkpoint.id}>
                <Button
                  type="button"
                  variant="ghost"
                  disabled={disabled}
                  aria-label={labels.openCheckpoint(checkpointLabel)}
                  onClick={() => openCheckpoint(checkpoint.id)}
                  className={cn("h-auto w-full justify-start gap-3 px-2 py-2 text-left", active?.id === checkpoint.id && "bg-accent")}
                >
                  <span className="flex w-12 shrink-0 items-center gap-1 text-xs tabular-nums text-muted-foreground">{complete ? <MdCheck className="size-3.5 text-foreground" aria-hidden="true" /> : null}{formatTime(checkpoint.atMs)}</span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium">{checkpointLabel}</span>
                    <span className="block text-xs font-normal text-muted-foreground">{status}</span>
                  </span>
                </Button>
              </li>;
            })}
          </ol>
        </div> : null}
      </CardContent>

      {active ? <div data-slot="interactive-media-checkpoint" className="border-t px-5 py-5 sm:px-6">
        <div className="mx-auto grid max-w-3xl gap-4">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="text-xs font-medium text-primary">{formatTime(active.atMs)} · {active.required === false ? labels.optional : labels.required}</p>
              <h3 className="mt-1 font-semibold">{localText(active.label) ?? labels.checkpoints}</h3>
            </div>
            <Button type="button" variant="ghost" size="icon-sm" onClick={() => commit({ ...state, activeCheckpointId: undefined })} disabled={disabled} aria-label={labels.close}><MdClose className="size-4" aria-hidden="true" /></Button>
          </div>
          <Separator />
          {renderActivity(active.activity, {
            checkpointId: active.id,
            completed: state.completedCheckpointIds.includes(active.id),
            disabled,
            complete: () => markComplete(active.id),
            close: () => commit({ ...state, activeCheckpointId: undefined }),
          })}
          <div className="flex flex-wrap gap-2">
            <Button type="button" onClick={() => markComplete(active.id)} disabled={disabled || state.completedCheckpointIds.includes(active.id)}>{labels.markComplete}</Button>
            <Button type="button" variant="outline" onClick={() => commit({ ...state, activeCheckpointId: undefined })} disabled={disabled}>{labels.close}</Button>
          </div>
        </div>
      </div> : null}

      {definition.media.transcript?.length ? <div className="border-t">
        <div className="px-5 py-4 sm:px-6"><h3 className="text-sm font-semibold">{labels.transcript}</h3></div>
        <ol className="max-h-80 overflow-y-auto border-t px-3 py-2 sm:px-4">
          {definition.media.transcript.map((cue) => {
            const cueActive = state.positionMs >= cue.startMs && state.positionMs < cue.endMs;
            return <li key={cue.id}>
              <button
                type="button"
                disabled={disabled}
                onClick={() => { controllerRef.current?.seek(cue.startMs); commit({ ...state, positionMs: cue.startMs }); }}
                className={cn("grid w-full grid-cols-[3.5rem_1fr] gap-3 rounded-md px-3 py-2.5 text-left text-sm transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50", cueActive && "bg-accent")}
              >
                <span className={cn("pt-0.5 text-xs tabular-nums", cueActive ? "text-foreground" : "text-muted-foreground")}>{formatTime(cue.startMs)}</span>
                <span className="leading-6">{cue.speaker ? <strong className="font-semibold">{localText(cue.speaker)}: </strong> : null}{localText(cue.text)}</span>
              </button>
            </li>;
          })}
        </ol>
      </div> : null}
    </Card>
  </section>;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

