import * as React from "react";
import {
  MdCheck,
  MdDeleteOutline,
  MdGesture,
  MdLocationOn,
  MdShowChart,
  MdUndo,
} from "react-icons/md";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/didact/cn";

export type DrawingTool = "freehand" | "line" | "marker";

export interface DrawingPoint {
  /** Horizontal position normalized from 0 to 1. */
  x: number;
  /** Vertical position normalized from 0 to 1. */
  y: number;
}

export interface DrawingStroke {
  id: string;
  tool: DrawingTool;
  points: DrawingPoint[];
}

export interface DrawingResponseState {
  strokes: DrawingStroke[];
}

export interface DrawingResponseDefinition {
  id: string;
  title: string;
  description?: string;
  instructions?: string;
  background?: { src: string; alt: string };
  tools?: DrawingTool[];
}

export interface DrawingEvaluation {
  status: "correct" | "partial" | "incorrect";
  feedback: string;
}

export type DrawingResponseResult =
  | { status: "ungraded"; strokes: DrawingStroke[] }
  | ({ strokes: DrawingStroke[] } & DrawingEvaluation);

export interface DrawingResponseLabels {
  activity: string;
  loading: string;
  empty: string;
  freehand: string;
  line: string;
  marker: string;
  undo: string;
  clear: string;
  submit: string;
  submitting: string;
  responseDetails: string;
  noStrokes: string;
  stroke: string;
  tool: string;
  points: string;
  remove: string;
  coordinates: string;
  coordinateHelp: string;
  x: string;
  y: string;
  addMarker: string;
  canvasHelp: string;
}

const defaultLabels: DrawingResponseLabels = {
  activity: "Drawing response",
  loading: "The drawing activity is still loading.",
  empty: "There is no drawing activity to display.",
  freehand: "Draw",
  line: "Line",
  marker: "Marker",
  undo: "Undo",
  clear: "Clear",
  submit: "Submit response",
  submitting: "Checking response…",
  responseDetails: "Response details",
  noStrokes: "No marks yet.",
  stroke: "Mark",
  tool: "Tool",
  points: "Coordinates",
  remove: "Remove",
  coordinates: "Add by coordinates",
  coordinateHelp: "Enter percentages from 0 to 100. This is an accessible alternative to drawing with a pointer.",
  x: "Horizontal position",
  y: "Vertical position",
  addMarker: "Add marker",
  canvasHelp: "Draw with a pointer. With the canvas focused, use the arrow keys to position the cursor and Space to add a marker.",
};

export interface DrawingResponseProps extends Omit<React.ComponentPropsWithoutRef<"section">, "children" | "title" | "onChange"> {
  definition?: DrawingResponseDefinition;
  state?: DrawingResponseState;
  defaultState?: DrawingResponseState;
  onStateChange?: (state: DrawingResponseState) => void;
  evaluate?: (strokes: DrawingStroke[]) => DrawingEvaluation | Promise<DrawingEvaluation>;
  onResult?: (result: DrawingResponseResult) => void;
  labels?: Partial<DrawingResponseLabels>;
  disabled?: boolean;
  streaming?: boolean;
}

const EMPTY_STATE: DrawingResponseState = { strokes: [] };
const ICONS = { freehand: MdGesture, line: MdShowChart, marker: MdLocationOn };
const VIEWBOX_WIDTH = 1000;
const VIEWBOX_HEIGHT = 600;

function clamp(value: number): number {
  return Math.max(0, Math.min(1, value));
}

function coordinateLabel(point: DrawingPoint): string {
  return `${Math.round(point.x * 100)}%, ${Math.round(point.y * 100)}%`;
}

function makeId(): string {
  return `mark-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

export const DrawingResponse = React.forwardRef<HTMLElement, DrawingResponseProps>(function DrawingResponse(
  { definition, state: controlledState, defaultState = EMPTY_STATE, onStateChange, evaluate, onResult, labels, disabled = false, streaming = false, className, ...props },
  ref,
) {
  const text = { ...defaultLabels, ...labels };
  const [internalState, setInternalState] = React.useState(defaultState);
  const [tool, setTool] = React.useState<DrawingTool>(definition?.tools?.[0] ?? "freehand");
  const [draft, setDraft] = React.useState<DrawingStroke>();
  const [keyboardPoint, setKeyboardPoint] = React.useState<DrawingPoint>({ x: 0.5, y: 0.5 });
  const [coordinateX, setCoordinateX] = React.useState(50);
  const [coordinateY, setCoordinateY] = React.useState(50);
  const [evaluation, setEvaluation] = React.useState<DrawingEvaluation>();
  const [submitting, setSubmitting] = React.useState(false);
  const titleId = React.useId();
  const instructionsId = React.useId();
  const coordinateHelpId = React.useId();
  const state = controlledState ?? internalState;
  const availableTools = definition?.tools?.length ? definition.tools : (["freehand", "line", "marker"] as DrawingTool[]);

  React.useEffect(() => {
    if (!availableTools.includes(tool)) setTool(availableTools[0] ?? "freehand");
  }, [availableTools, tool]);

  const commit = React.useCallback((strokes: DrawingStroke[]) => {
    const next = { strokes };
    if (controlledState === undefined) setInternalState(next);
    onStateChange?.(next);
    setEvaluation(undefined);
  }, [controlledState, onStateChange]);

  if (!definition) {
    return <section ref={ref} aria-label={text.activity} className={cn("rounded-xl border p-6 text-sm text-muted-foreground", className)} {...props}><p role={streaming ? "status" : undefined}>{streaming ? text.loading : text.empty}</p></section>;
  }

  const pointFromEvent = (event: React.PointerEvent<SVGSVGElement>): DrawingPoint => {
    const rect = event.currentTarget.getBoundingClientRect();
    return { x: clamp((event.clientX - rect.left) / Math.max(rect.width, 1)), y: clamp((event.clientY - rect.top) / Math.max(rect.height, 1)) };
  };
  const startStroke = (event: React.PointerEvent<SVGSVGElement>) => {
    if (disabled || event.button !== 0) return;
    const point = pointFromEvent(event);
    if (tool === "marker") commit([...state.strokes, { id: makeId(), tool, points: [point] }]);
    else {
      event.currentTarget.setPointerCapture?.(event.pointerId);
      setDraft({ id: makeId(), tool, points: [point] });
    }
  };
  const moveStroke = (event: React.PointerEvent<SVGSVGElement>) => {
    if (!draft || !event.currentTarget.hasPointerCapture?.(event.pointerId)) return;
    const point = pointFromEvent(event);
    setDraft({ ...draft, points: draft.tool === "line" ? [draft.points[0]!, point] : [...draft.points, point] });
  };
  const finishStroke = (event: React.PointerEvent<SVGSVGElement>) => {
    if (!draft) return;
    event.currentTarget.releasePointerCapture?.(event.pointerId);
    const point = pointFromEvent(event);
    const finished = draft.tool === "line" ? { ...draft, points: [draft.points[0]!, point] } : { ...draft, points: [...draft.points, point] };
    commit([...state.strokes, finished]);
    setDraft(undefined);
  };
  const addMarker = (point: DrawingPoint) => commit([...state.strokes, { id: makeId(), tool: "marker", points: [{ x: clamp(point.x), y: clamp(point.y) }] }]);
  const onCanvasKeyDown = (event: React.KeyboardEvent<SVGSVGElement>) => {
    const delta = event.shiftKey ? 0.05 : 0.01;
    const movement: Partial<Record<string, DrawingPoint>> = {
      ArrowLeft: { x: -delta, y: 0 }, ArrowRight: { x: delta, y: 0 }, ArrowUp: { x: 0, y: -delta }, ArrowDown: { x: 0, y: delta },
    };
    if (movement[event.key]) {
      event.preventDefault(); const change = movement[event.key]!;
      setKeyboardPoint((current) => ({ x: clamp(current.x + change.x), y: clamp(current.y + change.y) }));
    } else if (event.key === " " || event.key === "Enter") {
      event.preventDefault(); if (!disabled) addMarker(keyboardPoint);
    }
  };
  const submit = async () => {
    if (disabled || submitting || state.strokes.length === 0) return;
    setSubmitting(true);
    try {
      if (!evaluate) { onResult?.({ status: "ungraded", strokes: state.strokes }); return; }
      const result = await evaluate(state.strokes); setEvaluation(result); onResult?.({ ...result, strokes: state.strokes });
    } finally { setSubmitting(false); }
  };
  const allStrokes = draft ? [...state.strokes, draft] : state.strokes;

  return (
    <section ref={ref} aria-labelledby={titleId} className={cn("w-full", className)} {...props}>
      <Card>
        <CardHeader className="gap-1">
          <CardTitle><h2 id={titleId}>{definition.title}</h2></CardTitle>
          {definition.description ? <CardDescription>{definition.description}</CardDescription> : null}
        </CardHeader>
        <CardContent className="space-y-5">
          {definition.instructions ? <p id={instructionsId} className="text-sm text-muted-foreground">{definition.instructions}</p> : <span id={instructionsId} className="sr-only">{text.canvasHelp}</span>}

          <div className="flex flex-wrap items-center gap-1 border-b pb-3" role="toolbar" aria-label={text.activity}>
            {availableTools.map((item) => { const Icon = ICONS[item]; return <Button key={item} type="button" size="sm" variant={tool === item ? "secondary" : "ghost"} aria-pressed={tool === item} disabled={disabled} onClick={() => setTool(item)}><Icon aria-hidden className="mr-1.5" />{text[item]}</Button>; })}
            <span className="mx-1 h-5 w-px bg-border" aria-hidden />
            <Button type="button" size="icon" variant="ghost" aria-label={text.undo} title={text.undo} disabled={disabled || state.strokes.length === 0} onClick={() => commit(state.strokes.slice(0, -1))}><MdUndo aria-hidden /></Button>
            <Button type="button" size="icon" variant="ghost" aria-label={text.clear} title={text.clear} disabled={disabled || state.strokes.length === 0} onClick={() => commit([])}><MdDeleteOutline aria-hidden /></Button>
          </div>

          <div className="overflow-hidden rounded-lg border bg-muted/20">
            <svg
              viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
              preserveAspectRatio="xMidYMid meet"
              className={cn("block aspect-[5/3] w-full touch-none outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2", disabled && "cursor-not-allowed opacity-60")}
              role="img" aria-label={definition.background?.alt ?? text.activity} aria-describedby={instructionsId}
              tabIndex={disabled ? -1 : 0}
              onKeyDown={onCanvasKeyDown}
              onPointerDown={startStroke} onPointerMove={moveStroke} onPointerUp={finishStroke} onPointerCancel={() => setDraft(undefined)}
            >
              {definition.background ? <image href={definition.background.src} x="0" y="0" width={VIEWBOX_WIDTH} height={VIEWBOX_HEIGHT} preserveAspectRatio="xMidYMid slice" /> : <rect width={VIEWBOX_WIDTH} height={VIEWBOX_HEIGHT} fill="hsl(var(--muted))" opacity="0.25" />}
              {allStrokes.map((stroke) => {
                const points = stroke.points.map((point) => `${point.x * VIEWBOX_WIDTH},${point.y * VIEWBOX_HEIGHT}`).join(" ");
                if (stroke.tool === "marker") { const point = stroke.points[0]!; return <g key={stroke.id} transform={`translate(${point.x * VIEWBOX_WIDTH} ${point.y * VIEWBOX_HEIGHT})`}><circle r="18" fill="hsl(var(--background))" stroke="hsl(var(--primary))" strokeWidth="8"/><circle r="4" fill="hsl(var(--primary))" /></g>; }
                return <polyline key={stroke.id} points={points} fill="none" stroke="hsl(var(--primary))" strokeWidth={stroke.tool === "line" ? 8 : 10} strokeLinecap="round" strokeLinejoin="round" />;
              })}
              <g aria-hidden opacity="0.7" transform={`translate(${keyboardPoint.x * VIEWBOX_WIDTH} ${keyboardPoint.y * VIEWBOX_HEIGHT})`}><path d="M-12 0H12M0-12V12" stroke="hsl(var(--foreground))" strokeWidth="3" /></g>
            </svg>
          </div>
          <p className="text-xs text-muted-foreground">{text.canvasHelp}</p>

          <details className="rounded-lg border px-4 py-3">
            <summary className="cursor-pointer text-sm font-medium">{text.coordinates}</summary>
            <p id={coordinateHelpId} className="mt-2 text-xs text-muted-foreground">{text.coordinateHelp}</p>
            <div className="mt-3 grid gap-3 sm:grid-cols-[1fr_1fr_auto] sm:items-end">
              <div className="space-y-1.5"><Label htmlFor={`${titleId}-x`}>{text.x} (%)</Label><Input id={`${titleId}-x`} type="number" min="0" max="100" value={coordinateX} disabled={disabled} aria-describedby={coordinateHelpId} onChange={(event) => setCoordinateX(Number(event.target.value))} /></div>
              <div className="space-y-1.5"><Label htmlFor={`${titleId}-y`}>{text.y} (%)</Label><Input id={`${titleId}-y`} type="number" min="0" max="100" value={coordinateY} disabled={disabled} aria-describedby={coordinateHelpId} onChange={(event) => setCoordinateY(Number(event.target.value))} /></div>
              <Button type="button" variant="outline" disabled={disabled || !Number.isFinite(coordinateX) || !Number.isFinite(coordinateY)} onClick={() => addMarker({ x: coordinateX / 100, y: coordinateY / 100 })}><MdLocationOn aria-hidden className="mr-1.5" />{text.addMarker}</Button>
            </div>
          </details>

          <div>
            <h3 className="mb-2 text-sm font-medium">{text.responseDetails}</h3>
            {state.strokes.length === 0 ? <p className="text-sm text-muted-foreground">{text.noStrokes}</p> : <ol className="divide-y rounded-lg border">{state.strokes.map((stroke, index) => <li key={stroke.id} className="flex items-center gap-3 px-3 py-2 text-sm"><span className="min-w-0 flex-1"><span className="font-medium">{text.stroke} {index + 1}</span><span className="ml-2 text-muted-foreground">{text[stroke.tool]} · {stroke.points.length === 1 ? coordinateLabel(stroke.points[0]!) : `${coordinateLabel(stroke.points[0]!)} → ${coordinateLabel(stroke.points.at(-1)!)}`}</span></span><Button type="button" size="icon" variant="ghost" aria-label={`${text.remove} ${text.stroke} ${index + 1}`} disabled={disabled} onClick={() => commit(state.strokes.filter(({ id }) => id !== stroke.id))}><MdDeleteOutline aria-hidden /></Button></li>)}</ol>}
          </div>

          {evaluation ? <div role="status" className="rounded-lg border px-4 py-3 text-sm"><p className="font-medium capitalize">{evaluation.status}</p><p className="mt-1 text-muted-foreground">{evaluation.feedback}</p></div> : null}
          <div className="flex justify-end"><Button type="button" disabled={disabled || submitting || state.strokes.length === 0} onClick={submit}><MdCheck aria-hidden className="mr-1.5" />{submitting ? text.submitting : text.submit}</Button></div>
        </CardContent>
      </Card>
    </section>
  );
});

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

import type {
  ComponentFamily,
  ComponentRole,
  LearnerActionFacet,
  LearningContextFacet,
  LearningPurposeFacet,
  RepresentationFacet,
  SubjectFacet,
} from "./taxonomy";

export type LocalizedText = string | Readonly<Record<string, string>>;

export type ConditionOperator =
  | "equals"
  | "not-equals"
  | "contains"
  | "not-contains"
  | "greater-than"
  | "less-than"
  | "is-set"
  | "is-not-set";

export interface AuthoringCondition {
  readonly path: string;
  readonly operator: ConditionOperator;
  readonly value?: string | number | boolean | readonly (string | number)[];
}

export type RequirednessLevel = "required" | "progressive" | "optional";

export interface ConditionalRequiredness {
  readonly level: RequirednessLevel;
  readonly when: AuthoringCondition;
}

/**
 * `true` and a bare condition are retained for backwards compatibility: they mean "required"
 * always and "required when the condition matches", respectively.
 */
export type Requiredness =
  | boolean
  | RequirednessLevel
  | AuthoringCondition
  | ConditionalRequiredness;

export interface AuthoringOption {
  readonly value: string;
  readonly label: LocalizedText;
  readonly description?: LocalizedText;
}

interface AuthoringFieldBase {
  readonly key: string;
  readonly label: LocalizedText;
  readonly description?: LocalizedText;
  readonly required?: Requiredness;
  readonly visibleWhen?: AuthoringCondition;
  readonly defaultValue?: unknown;
  readonly i18n?: boolean;
  readonly group?: string;
}

export interface TextAuthoringField extends AuthoringFieldBase {
  readonly kind: "text" | "rich-text";
  readonly minLength?: number;
  readonly maxLength?: number;
  readonly pattern?: string;
  readonly multiline?: boolean;
}

export interface NumberAuthoringField extends AuthoringFieldBase {
  readonly kind: "number";
  readonly min?: number;
  readonly max?: number;
  readonly step?: number;
  readonly unit?: LocalizedText;
}

export interface BooleanAuthoringField extends AuthoringFieldBase {
  readonly kind: "boolean";
}

export interface ChoiceAuthoringField extends AuthoringFieldBase {
  readonly kind: "select" | "multi-select";
  readonly options: readonly AuthoringOption[];
}

export interface AssetAuthoringField extends AuthoringFieldBase {
  readonly kind: "asset";
  readonly accept?: readonly string[];
  readonly altTextField?: string;
}

export interface ObjectAuthoringField extends AuthoringFieldBase {
  readonly kind: "object";
  readonly fields: readonly AuthoringField[];
}

export interface ListAuthoringField extends AuthoringFieldBase {
  readonly kind: "list";
  readonly item: AuthoringField;
  readonly minItems?: number;
  readonly maxItems?: number;
  readonly reorderable?: boolean;
}

export type AuthoringField =
  | TextAuthoringField
  | NumberAuthoringField
  | BooleanAuthoringField
  | ChoiceAuthoringField
  | AssetAuthoringField
  | ObjectAuthoringField
  | ListAuthoringField;

export interface AuthoringSchema {
  readonly version: string;
  readonly fields: readonly AuthoringField[];
  readonly supportsLocalization?: boolean;
}

export type EvidenceStrength = "high" | "moderate" | "low" | "not-evaluated";

export interface EvidenceReference {
  readonly id: string;
  readonly strength: EvidenceStrength;
  readonly citation: string;
  readonly url?: string;
  readonly claim: string;
  readonly limitations?: string;
}

export interface AccessibilityMetadata {
  readonly keyboard: "full" | "alternative" | "not-applicable" | "unsupported";
  readonly screenReader: "full" | "partial" | "not-applicable" | "unsupported";
  readonly draggingAlternative?: boolean;
  readonly requiresAltText?: boolean;
  readonly captions?: "required" | "recommended" | "not-applicable";
  readonly wcagCriteria?: readonly string[];
  readonly notes?: string;
}

export interface QtiMapping {
  readonly interaction: string;
  readonly fidelity: "exact" | "approximate" | "none";
  readonly version?: "3.0";
  readonly notes?: string;
}

export interface XapiMapping {
  readonly interactionType?:
    | "true-false"
    | "choice"
    | "fill-in"
    | "long-fill-in"
    | "matching"
    | "performance"
    | "sequencing"
    | "likert"
    | "numeric"
    | "other";
  readonly verbs?: readonly string[];
  readonly notes?: string;
}

export interface InteroperabilityMappings {
  readonly qti?: QtiMapping | readonly QtiMapping[];
  readonly xapi?: XapiMapping | readonly XapiMapping[];
}

export interface OptionalDependency {
  readonly package: string;
  readonly purpose: string;
  readonly requiredFor?: readonly string[];
  readonly fallback?: string;
}

export interface MigrationMetadata {
  readonly from: string;
  readonly to: string;
  readonly description: string;
  readonly breaking?: boolean;
}

export interface VersionMetadata {
  readonly schema: string;
  readonly component: string;
  readonly migrations?: readonly MigrationMetadata[];
}

export interface CatalogLifecycle {
  readonly availability: "available" | "planned" | "deprecated";
  readonly maturity: "draft" | "experimental" | "stable";
}

export interface ComponentVariant {
  readonly id: string;
  readonly name: LocalizedText;
  readonly description?: LocalizedText;
  readonly availability?: CatalogLifecycle["availability"];
}

export interface ComponentFacets {
  readonly subjects: readonly SubjectFacet[];
  readonly representations: readonly RepresentationFacet[];
  readonly learnerActions: readonly LearnerActionFacet[];
  readonly purposes: readonly LearningPurposeFacet[];
  readonly contexts?: readonly LearningContextFacet[];
}

export interface ComponentManifest {
  readonly id: string;
  readonly name: LocalizedText;
  readonly description: LocalizedText;
  readonly role: ComponentRole;
  readonly families: readonly ComponentFamily[];
  readonly facets: ComponentFacets;
  readonly lifecycle: CatalogLifecycle;
  readonly version: VersionMetadata;
  readonly authoring: AuthoringSchema;
  readonly evidence: readonly EvidenceReference[];
  readonly accessibility: AccessibilityMetadata;
  readonly mappings?: InteroperabilityMappings;
  readonly variants?: readonly ComponentVariant[];
  readonly optionalDependencies?: readonly OptionalDependency[];
  readonly capabilities?: readonly string[];
  readonly tags?: readonly string[];
}

export type CatalogCollectionKind = "foundation" | "subject" | "context" | "experience";
export type CatalogCollectionStatus = "draft" | "available" | "deprecated";
export type CollectionItemRole = "required" | "recommended" | "optional";

export interface CollectionItem {
  readonly manifestId: string;
  readonly typeId?: string;
  readonly role: CollectionItemRole;
  readonly reason: string;
}

export interface CatalogCollectionKit {
  readonly name: string;
  readonly includeRoles: readonly CollectionItemRole[];
}

export interface CatalogCollection {
  readonly id: string;
  readonly version: string;
  readonly slug: string;
  readonly title: LocalizedText;
  readonly description: LocalizedText;
  readonly kind: CatalogCollectionKind;
  readonly status: CatalogCollectionStatus;
  readonly facets?: Partial<ComponentFacets>;
  readonly items: readonly CollectionItem[];
  readonly kit?: CatalogCollectionKit;
  readonly tags?: readonly string[];
}

export type ResponseStatus = "draft" | "streaming" | "submitted";

interface ResponseBase {
  readonly id: string;
  readonly componentId: string;
  readonly status: ResponseStatus;
  readonly answeredAt?: string;
  readonly durationMs?: number;
}

export type Response = ResponseBase &
  (
    | { readonly kind: "choice"; readonly value: readonly string[] }
    | { readonly kind: "text"; readonly value: string }
    | { readonly kind: "numeric"; readonly value: number; readonly unit?: string }
    | { readonly kind: "boolean"; readonly value: boolean }
    | { readonly kind: "ordering"; readonly value: readonly string[] }
    | { readonly kind: "matching"; readonly value: Readonly<Record<string, string | readonly string[]>> }
    | { readonly kind: "points"; readonly value: readonly { readonly x: number; readonly y: number }[] }
    | { readonly kind: "file" | "audio" | "drawing"; readonly value: string }
    | { readonly kind: "composite"; readonly value: readonly Response[] }
  );

export interface Feedback {
  readonly kind: "informative" | "corrective" | "hint" | "explanation" | "model-answer";
  readonly message: LocalizedText;
  readonly target?: string;
  readonly priority?: "primary" | "secondary";
}

export interface Result {
  readonly responseId: string;
  readonly status: "ungraded" | "correct" | "incorrect" | "partial";
  readonly score?: number;
  readonly maxScore?: number;
  readonly normalizedScore?: number;
  readonly feedback?: readonly Feedback[];
  readonly outcomes?: Readonly<Record<string, string | number | boolean>>;
  readonly evaluatedAt?: string;
}

export interface ValidationIssue {
  readonly path: string;
  readonly code: string;
  readonly message: string;
  readonly severity: "error" | "warning";
}

export interface AuthoringValidationOptions {
  readonly mode: "complete" | "streaming";
}

export type ValidationResult<T> =
  | { readonly success: true; readonly data: T; readonly issues: readonly ValidationIssue[] }
  | { readonly success: false; readonly issues: readonly ValidationIssue[] };

import type { LocalizedText, ValidationIssue, ValidationResult } from "./types";

export const EQUATION_WORKBENCH_SCHEMA_VERSION = "1.0.0" as const;

export interface EquationExpression {
  readonly notation: "latex" | "plain-text";
  readonly value: string;
  readonly accessibleText?: LocalizedText;
}

export interface EquationStepPolicy {
  readonly minimumSteps?: number;
  readonly maximumSteps?: number;
  readonly requireJustification?: boolean;
}

export interface EquationWorkbenchDefinition {
  readonly schemaVersion: typeof EQUATION_WORKBENCH_SCHEMA_VERSION;
  readonly id: string;
  readonly title: LocalizedText;
  readonly prompt: LocalizedText;
  readonly initialExpression: EquationExpression;
  readonly goal?: LocalizedText;
  readonly variables?: readonly string[];
  readonly stepPolicy?: EquationStepPolicy;
}

export interface EquationWorkbenchStep {
  readonly id: string;
  readonly expression: EquationExpression;
  readonly justification?: string;
}

export interface EquationWorkbenchState {
  readonly status: "draft" | "submitted";
  readonly steps: readonly EquationWorkbenchStep[];
}

export type EquationWorkbenchEvent =
  | { readonly type: "step-added"; readonly step: EquationWorkbenchStep }
  | { readonly type: "step-updated"; readonly step: EquationWorkbenchStep }
  | { readonly type: "step-removed"; readonly stepId: string }
  | { readonly type: "submitted" };

/** Evaluation is supplied by the host; the schema never parses or executes expressions. */
export interface EquationWorkbenchResult {
  readonly status: "ungraded" | "correct" | "incorrect" | "partial";
  readonly state: EquationWorkbenchState;
  readonly score?: number;
  readonly maxScore?: number;
  readonly feedback?: readonly LocalizedText[];
  readonly evaluatedAt?: string;
  readonly events?: readonly EquationWorkbenchEvent[];
}

export interface EquationWorkbenchValidationOptions { readonly mode?: "complete" | "streaming" }

const ID = /^[a-z0-9]+(?:[.-][a-z0-9]+)*$/;
const VARIABLE = /^[A-Za-z][A-Za-z0-9_]*$/;
const record = (value: unknown): value is Record<string, unknown> => typeof value === "object" && value !== null && !Array.isArray(value);
const text = (value: unknown): boolean => typeof value === "string" ? value.trim().length > 0 : record(value) && Object.keys(value).length > 0 && Object.values(value).every((entry) => typeof entry === "string" && entry.trim().length > 0);
const finite = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value);
const identifier = (value: unknown): value is string => typeof value === "string" && ID.test(value);
const add = (issues: ValidationIssue[], path: string, code: string, message: string): void => { issues.push({ path, code, message, severity: "error" }); };

function validateExpression(value: unknown, path: string, issues: ValidationIssue[], complete: boolean): void {
  if (!record(value)) { if (complete) add(issues, path, "equation.expression", "Expression is required."); return; }
  if (value.notation !== "latex" && value.notation !== "plain-text") add(issues, `${path}.notation`, "equation.notation", "notation must be latex or plain-text.");
  if (complete && (typeof value.value !== "string" || value.value.trim().length === 0)) add(issues, `${path}.value`, "equation.expression-value", "Expression value is required.");
  if (value.value !== undefined && typeof value.value !== "string") add(issues, `${path}.value`, "equation.expression-value", "Expression value must be a string.");
  if (value.accessibleText !== undefined && !text(value.accessibleText)) add(issues, `${path}.accessibleText`, "equation.accessible-text", "accessibleText must contain text.");
}

export function validateEquationWorkbenchDefinition(input: unknown, options: EquationWorkbenchValidationOptions = {}): ValidationResult<EquationWorkbenchDefinition> {
  const issues: ValidationIssue[] = []; const complete = (options.mode ?? "complete") === "complete";
  if (!record(input)) return { success: false, issues: [{ path: "$", code: "equation.object", message: "Equation workbench must be an object.", severity: "error" }] };
  if (input.schemaVersion !== undefined ? input.schemaVersion !== EQUATION_WORKBENCH_SCHEMA_VERSION : complete) add(issues, "schemaVersion", "equation.version", `schemaVersion must be ${EQUATION_WORKBENCH_SCHEMA_VERSION}.`);
  if (input.id !== undefined ? !identifier(input.id) : complete) add(issues, "id", "equation.id", "id must be a stable lowercase identifier.");
  if (complete && !text(input.title)) add(issues, "title", "equation.title", "title is required."); else if (input.title !== undefined && !text(input.title)) add(issues, "title", "equation.title", "title must contain text.");
  if (complete && !text(input.prompt)) add(issues, "prompt", "equation.prompt", "prompt is required."); else if (input.prompt !== undefined && !text(input.prompt)) add(issues, "prompt", "equation.prompt", "prompt must contain text.");
  validateExpression(input.initialExpression, "initialExpression", issues, complete);
  if (input.goal !== undefined && !text(input.goal)) add(issues, "goal", "equation.goal", "goal must contain text.");
  if (input.variables !== undefined) {
    if (!Array.isArray(input.variables)) add(issues, "variables", "equation.variables", "variables must be a list.");
    else { const seen = new Set<string>(); input.variables.forEach((entry, index) => { if (typeof entry !== "string" || !VARIABLE.test(entry)) add(issues, `variables[${index}]`, "equation.variable", "Variable names must be valid identifiers."); else if (seen.has(entry)) add(issues, `variables[${index}]`, "equation.variable-duplicate", "Variable names must be unique."); else seen.add(entry); }); }
  }
  if (input.stepPolicy !== undefined) {
    if (!record(input.stepPolicy)) add(issues, "stepPolicy", "equation.step-policy", "stepPolicy must be an object.");
    else {
      const min = input.stepPolicy.minimumSteps; const max = input.stepPolicy.maximumSteps;
      if (min !== undefined && (!Number.isInteger(min) || Number(min) < 0)) add(issues, "stepPolicy.minimumSteps", "equation.minimum-steps", "minimumSteps must be a non-negative integer.");
      if (max !== undefined && (!Number.isInteger(max) || Number(max) < 1)) add(issues, "stepPolicy.maximumSteps", "equation.maximum-steps", "maximumSteps must be a positive integer.");
      if (Number.isInteger(min) && Number.isInteger(max) && Number(min) > Number(max)) add(issues, "stepPolicy", "equation.step-range", "minimumSteps cannot exceed maximumSteps.");
      if (input.stepPolicy.requireJustification !== undefined && typeof input.stepPolicy.requireJustification !== "boolean") add(issues, "stepPolicy.requireJustification", "equation.justification-policy", "requireJustification must be boolean.");
    }
  }
  return issues.length ? { success: false, issues } : { success: true, data: input as unknown as EquationWorkbenchDefinition, issues };
}

function validateStep(value: unknown, path: string, issues: ValidationIssue[]): void {
  if (!record(value)) { add(issues, path, "equation.step", "Step must be an object."); return; }
  if (!identifier(value.id)) add(issues, `${path}.id`, "equation.step-id", "Step id must be stable.");
  validateExpression(value.expression, `${path}.expression`, issues, true);
  if (value.justification !== undefined && (typeof value.justification !== "string" || value.justification.trim().length === 0)) add(issues, `${path}.justification`, "equation.justification", "Justification must contain text.");
}

export function validateEquationWorkbenchState(input: unknown, definition?: EquationWorkbenchDefinition): ValidationResult<EquationWorkbenchState> {
  const issues: ValidationIssue[] = [];
  if (!record(input)) return { success: false, issues: [{ path: "$", code: "equation.state", message: "State must be an object.", severity: "error" }] };
  if (input.status !== "draft" && input.status !== "submitted") add(issues, "status", "equation.state-status", "status must be draft or submitted.");
  if (!Array.isArray(input.steps)) add(issues, "steps", "equation.steps", "steps must be a list.");
  else {
    const ids = new Set<string>(); input.steps.forEach((step, index) => { validateStep(step, `steps[${index}]`, issues); if (record(step) && identifier(step.id)) { if (ids.has(step.id)) add(issues, `steps[${index}].id`, "equation.step-duplicate", "Step ids must be unique."); ids.add(step.id); } });
    const policy = definition?.stepPolicy;
    if (input.status === "submitted" && policy?.minimumSteps !== undefined && input.steps.length < policy.minimumSteps) add(issues, "steps", "equation.steps-minimum", "Submitted state does not meet minimumSteps.");
    if (policy?.maximumSteps !== undefined && input.steps.length > policy.maximumSteps) add(issues, "steps", "equation.steps-maximum", "State exceeds maximumSteps.");
    if (policy?.requireJustification && input.status === "submitted") input.steps.forEach((step, index) => { if (!record(step) || typeof step.justification !== "string" || !step.justification.trim()) add(issues, `steps[${index}].justification`, "equation.justification-required", "Every submitted step requires justification."); });
  }
  return issues.length ? { success: false, issues } : { success: true, data: input as unknown as EquationWorkbenchState, issues };
}

export function validateEquationWorkbenchResult(input: unknown, definition?: EquationWorkbenchDefinition): ValidationResult<EquationWorkbenchResult> {
  const issues: ValidationIssue[] = [];
  if (!record(input)) return { success: false, issues: [{ path: "$", code: "equation.result", message: "Result must be an object.", severity: "error" }] };
  if (!["ungraded", "correct", "incorrect", "partial"].includes(String(input.status))) add(issues, "status", "equation.result-status", "Unknown result status.");
  const state = validateEquationWorkbenchState(input.state, definition); state.issues.forEach((entry) => issues.push({ ...entry, path: `state.${entry.path}` }));
  if (input.score !== undefined && !finite(input.score)) add(issues, "score", "equation.score", "score must be finite.");
  if (input.maxScore !== undefined && (!finite(input.maxScore) || input.maxScore <= 0)) add(issues, "maxScore", "equation.max-score", "maxScore must be positive.");
  if (finite(input.score) && finite(input.maxScore) && (input.score < 0 || input.score > input.maxScore)) add(issues, "score", "equation.score-range", "score must be between zero and maxScore.");
  if (input.feedback !== undefined && (!Array.isArray(input.feedback) || !input.feedback.every(text))) add(issues, "feedback", "equation.feedback", "feedback must be a list of localized text values.");
  if (input.events !== undefined) {
    if (!Array.isArray(input.events)) add(issues, "events", "equation.events", "events must be a list.");
    else input.events.forEach((event, index) => { const path = `events[${index}]`; if (!record(event)) { add(issues, path, "equation.event", "Event must be an object."); return; } if (event.type === "step-added" || event.type === "step-updated") validateStep(event.step, `${path}.step`, issues); else if (event.type === "step-removed") { if (!identifier(event.stepId)) add(issues, `${path}.stepId`, "equation.event-step", "stepId must be stable."); } else if (event.type !== "submitted") add(issues, `${path}.type`, "equation.event-type", "Unknown event type."); });
  }
  return issues.length ? { success: false, issues } : { success: true, data: input as unknown as EquationWorkbenchResult, issues };
}

