import * as React from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { cn } from "@/lib/didact/cn";

export type MeasurementInstrumentKind = "linear" | "dial";

export interface MeasurementLabDefinition {
  id: string;
  title: string;
  description?: string;
  instructions?: string;
  /** Fixed value displayed by the instrument for reading tasks. Omit for manipulable instruments. */
  observedReading?: number;
  instrument: {
    kind: MeasurementInstrumentKind;
    min: number;
    max: number;
    step: number;
    majorStep?: number;
    unit: string;
    label?: string;
    orientation?: "horizontal" | "vertical";
  };
}

export interface MeasurementLabState {
  reading: number | null;
}

export type MeasurementLabStatus = "correct" | "incorrect" | "partial" | "ungraded";

export interface MeasurementLabEvaluation {
  status: MeasurementLabStatus;
  feedback?: React.ReactNode;
}

export interface MeasurementLabResult extends MeasurementLabEvaluation {
  definitionId: string;
  reading: number;
  unit: string;
}

export interface MeasurementLabLabels {
  activity: string;
  loading: string;
  empty: string;
  instrument: string;
  reading: string;
  setReading: string;
  submit: string;
  submitting: string;
  submitted: string;
  instrumentAt: (value: string, unit: string) => string;
  instrumentBetween: (lower: string, upper: string, unit: string) => string;
}

const defaultLabels: MeasurementLabLabels = {
  activity: "Measurement lab",
  loading: "The instrument is still loading.",
  empty: "There is no instrument to measure yet.",
  instrument: "Instrument",
  reading: "Current reading",
  setReading: "Set the measured value",
  submit: "Submit reading",
  submitting: "Checking reading",
  submitted: "Reading submitted",
  instrumentAt: (value, unit) => `Indicator at ${value} ${unit}.`,
  instrumentBetween: (lower, upper, unit) => `Indicator between ${lower} and ${upper} ${unit}.`,
};

export interface MeasurementLabProps
  extends Omit<React.ComponentPropsWithoutRef<"section">, "children" | "title" | "onSubmit"> {
  definition?: MeasurementLabDefinition;
  state?: MeasurementLabState;
  defaultState?: MeasurementLabState;
  onStateChange?: (state: MeasurementLabState) => void;
  evaluate?: (
    state: MeasurementLabState,
    definition: MeasurementLabDefinition,
  ) => MeasurementLabEvaluation | Promise<MeasurementLabEvaluation>;
  onSubmit?: (result: MeasurementLabResult) => void;
  disabled?: boolean;
  streaming?: boolean;
  locale?: string;
  labels?: Partial<MeasurementLabLabels>;
}

function validDefinition(definition: MeasurementLabDefinition): boolean {
  const { min, max, step } = definition.instrument;
  return Number.isFinite(min) && Number.isFinite(max) && max > min && Number.isFinite(step) && step > 0
    && (definition.observedReading === undefined
      || (Number.isFinite(definition.observedReading) && definition.observedReading >= min && definition.observedReading <= max));
}

function precision(step: number): number {
  const fraction = String(step).split(".")[1];
  return Math.min(fraction?.length ?? 0, 6);
}

function normalizeReading(value: number, definition: MeasurementLabDefinition): number {
  const { min, max, step } = definition.instrument;
  const snapped = min + Math.round((value - min) / step) * step;
  return Number(Math.min(max, Math.max(min, snapped)).toFixed(precision(step)));
}

function formatReading(value: number, definition: MeasurementLabDefinition, locale: string): string {
  return new Intl.NumberFormat(locale, {
    minimumFractionDigits: precision(definition.instrument.step),
    maximumFractionDigits: precision(definition.instrument.step),
  }).format(value);
}

function ticks(definition: MeasurementLabDefinition): number[] {
  const { min, max, majorStep = (max - min) / 4 } = definition.instrument;
  if (!Number.isFinite(majorStep) || majorStep <= 0) return [min, max];
  const values: number[] = [];
  for (let value = min; value <= max + majorStep / 1000 && values.length < 30; value += majorStep) {
    values.push(Number(Math.min(value, max).toFixed(precision(majorStep))));
  }
  if (values.at(-1) !== max) values.push(max);
  return [...new Set(values)];
}

function LinearInstrument({ definition, reading, locale, accessibleReading }: {
  definition: MeasurementLabDefinition;
  reading: number;
  locale: string;
  accessibleReading: string;
}) {
  const { min, max } = definition.instrument;
  const position = ((reading - min) / (max - min)) * 100;
  return (
    <svg viewBox="0 0 640 150" role="img" aria-label={accessibleReading} className="h-auto w-full">
      <line x1="50" y1="72" x2="590" y2="72" className="stroke-border" strokeWidth="4" />
      {ticks(definition).map((value) => {
        const x = 50 + ((value - min) / (max - min)) * 540;
        return <g key={value}><line x1={x} y1="58" x2={x} y2="87" className="stroke-muted-foreground" strokeWidth="2" /><text x={x} y="113" textAnchor="middle" className="fill-muted-foreground text-[13px]">{formatReading(value, definition, locale)}</text></g>;
      })}
      <line x1={50 + position * 5.4} y1="35" x2={50 + position * 5.4} y2="91" className="stroke-foreground" strokeWidth="4" />
      <circle cx={50 + position * 5.4} cy="31" r="7" className="fill-foreground" />
    </svg>
  );
}

function DialInstrument({ definition, reading, locale, accessibleReading }: {
  definition: MeasurementLabDefinition;
  reading: number;
  locale: string;
  accessibleReading: string;
}) {
  const { min, max } = definition.instrument;
  const angle = 135 + ((reading - min) / (max - min)) * 270;
  const radians = (angle * Math.PI) / 180;
  const endX = 160 + Math.cos(radians) * 88;
  const endY = 155 + Math.sin(radians) * 88;
  return (
    <svg viewBox="0 0 320 260" role="img" aria-label={accessibleReading} className="mx-auto h-auto w-full max-w-sm">
      <path d="M 65 205 A 135 135 0 1 1 255 205" fill="none" className="stroke-border" strokeWidth="5" />
      {ticks(definition).map((value) => {
        const tickAngle = (135 + ((value - min) / (max - min)) * 270) * Math.PI / 180;
        const x1 = 160 + Math.cos(tickAngle) * 119;
        const y1 = 155 + Math.sin(tickAngle) * 119;
        const x2 = 160 + Math.cos(tickAngle) * 132;
        const y2 = 155 + Math.sin(tickAngle) * 132;
        const labelX = 160 + Math.cos(tickAngle) * 104;
        const labelY = 159 + Math.sin(tickAngle) * 104;
        return <g key={value}><line x1={x1} y1={y1} x2={x2} y2={y2} className="stroke-muted-foreground" strokeWidth="2" /><text x={labelX} y={labelY} dominantBaseline="middle" textAnchor="middle" className="fill-muted-foreground text-[10px]">{formatReading(value, definition, locale)}</text></g>;
      })}
      <line x1="160" y1="155" x2={endX} y2={endY} className="stroke-foreground" strokeWidth="5" strokeLinecap="round" />
      <circle cx="160" cy="155" r="9" className="fill-foreground" />
    </svg>
  );
}

export function MeasurementLab({
  definition,
  state,
  defaultState = { reading: null },
  onStateChange,
  evaluate,
  onSubmit,
  disabled = false,
  streaming = false,
  locale = "en",
  labels: labelsOverride,
  className,
  ...props
}: MeasurementLabProps) {
  const labels = { ...defaultLabels, ...labelsOverride };
  const [internalState, setInternalState] = React.useState(defaultState);
  const currentState = state ?? internalState;
  const [result, setResult] = React.useState<MeasurementLabResult | null>(null);
  const [submitting, setSubmitting] = React.useState(false);
  const inputId = React.useId();

  if (!definition || !validDefinition(definition)) {
    return <section aria-label={labels.activity} className={cn("w-full", className)} {...props}><Card><CardContent className="py-8 text-sm text-muted-foreground">{streaming ? labels.loading : labels.empty}</CardContent></Card></section>;
  }

  const { instrument } = definition;
  const displayReading = currentState.reading ?? normalizeReading((instrument.min + instrument.max) / 2, definition);
  const instrumentReading = definition.observedReading ?? displayReading;
  const majorTicks = ticks(definition);
  const exactTick = majorTicks.find((value) => Math.abs(value - instrumentReading) < instrument.step / 1000);
  const lowerTick = [...majorTicks].reverse().find((value) => value < instrumentReading) ?? instrument.min;
  const upperTick = majorTicks.find((value) => value > instrumentReading) ?? instrument.max;
  const accessibleReading = exactTick !== undefined
    ? labels.instrumentAt(formatReading(exactTick, definition, locale), instrument.unit)
    : labels.instrumentBetween(formatReading(lowerTick, definition, locale), formatReading(upperTick, definition, locale), instrument.unit);
  const commit = (reading: number) => {
    const next = { reading: normalizeReading(reading, definition) };
    if (state === undefined) setInternalState(next);
    onStateChange?.(next);
    setResult(null);
  };
  const submit = async () => {
    if (currentState.reading === null || submitting || disabled) return;
    setSubmitting(true);
    try {
      const evaluation = evaluate
        ? await evaluate(currentState, definition)
        : { status: "ungraded" as const };
      const next: MeasurementLabResult = {
        definitionId: definition.id,
        reading: currentState.reading,
        unit: instrument.unit,
        ...evaluation,
      };
      setResult(next);
      onSubmit?.(next);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <section aria-label={labels.activity} className={cn("w-full", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle>{definition.title}</CardTitle>
          {definition.description ? <CardDescription>{definition.description}</CardDescription> : null}
        </CardHeader>
        <CardContent className="space-y-6">
          {definition.instructions ? <p className="text-sm text-muted-foreground">{definition.instructions}</p> : null}
          <figure aria-label={instrument.label ?? labels.instrument} className="rounded-md border p-4">
            {instrument.kind === "dial"
              ? <DialInstrument definition={definition} reading={instrumentReading} locale={locale} accessibleReading={accessibleReading} />
              : <LinearInstrument definition={definition} reading={instrumentReading} locale={locale} accessibleReading={accessibleReading} />}
          </figure>
          <div className="space-y-3">
            <Label htmlFor={inputId}>{labels.setReading}</Label>
            <input id={inputId} type="range" min={instrument.min} max={instrument.max} step={instrument.step} value={displayReading} disabled={disabled} onChange={(event) => commit(event.currentTarget.valueAsNumber)} className="w-full accent-foreground" />
            <div className="flex items-end gap-3">
              <div className="flex-1 space-y-2">
                <Label htmlFor={`${inputId}-number`}>{labels.reading}</Label>
                <Input id={`${inputId}-number`} type="number" min={instrument.min} max={instrument.max} step={instrument.step} value={currentState.reading ?? ""} placeholder={formatReading(displayReading, definition, locale)} disabled={disabled} onChange={(event) => { if (event.currentTarget.value !== "") commit(event.currentTarget.valueAsNumber); }} />
              </div>
              <span className="pb-2 text-sm text-muted-foreground">{instrument.unit}</span>
            </div>
          </div>
          {result ? <div role="status" className="rounded-md border px-4 py-3 text-sm"><p className="font-medium">{labels.submitted}</p>{result.feedback ? <div className="mt-1 text-muted-foreground">{result.feedback}</div> : null}</div> : null}
        </CardContent>
        <CardFooter>
          <Button type="button" onClick={() => void submit()} disabled={disabled || submitting || currentState.reading === null}>{submitting ? labels.submitting : labels.submit}</Button>
        </CardFooter>
      </Card>
    </section>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * `cn` -- Didact's class-composition helper (docs/design-principles.md §3), mirrored here from
 * packages/core/src/lib/cn.ts so `@didact/ui` has no dependency on `@didact/core`: `clsx` resolves
 * conditional/array/falsy class inputs, `tailwind-merge` then resolves conflicting Tailwind
 * utilities (e.g. a caller's `className="px-4"` overriding this component's own `px-2`) by keeping
 * the last one instead of leaving both in the DOM. Every Didact component that accepts `className`
 * must merge it LAST through this helper, not a manual array-join, so a single instance can be
 * restyled inline without fighting the base classes.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

/**
 * Spaced-repetition agnostic interface.
 *
 * Source: `specs/education-components/research.md` Question 4 ("Which spaced-repetition
 * algorithm is reasonable without a heavy dependency, and how should its API be designed to be
 * agnostic of where state is persisted?"). The interface below is research.md's EXACT proposal,
 * derived from how `ts-fsrs` already solves the same problem.
 *
 * Key contract (RF-2 in `requirements.md`): the scheduler NEVER persists anything. It receives
 * the current state, returns the next state; the consuming project decides where that state
 * lives (localStorage, its own database, etc.). This is what lets SkillNet or any other consumer
 * integrate it without the library imposing a storage model.
 */

/**
 * Review state of a card. Deliberately opaque at the type level: each algorithm defines its own
 * internal shape (SM2State: n/EF/I; FSRSState: S/D/reps/lapses/dates; LeitnerState: an integer
 * box) without the consumer needing to know it — it just has to store it and return it as-is.
 */
export type ReviewState = Record<string, unknown>;

/**
 * Grade the user gives their own recall after seeing the answer. Vocabulary taken from
 * FSRS/Anki (research.md P4), also reusable for an SM-2 scheduler by mapping
 * "again"/"hard" to failure (q<3) and "good"/"easy" to success (q>=3).
 */
export type ReviewGrade = "again" | "hard" | "good" | "easy";

/**
 * Result of scheduling a review: the new opaque state to persist and the date the card becomes
 * due again. Retrieval-practice orchestrators (a layer above, in `@didact/core`, RF-2) use `dueAt` to
 * decide which card to show next.
 */
export interface ReviewResult {
  state: ReviewState;
  dueAt: Date;
}

/**
 * Contract each algorithm implements (SM-2, FSRS, and optionally Leitner as a "simple mode").
 * `schedule` is a pure function: the same (state, grade, now) always produces the same result,
 * with no side effects or I/O — a necessary condition for it to be persistence-agnostic.
 */
export interface SpacedRepetitionScheduler {
  /** Creates the initial state of a new card (first time it's seen). */
  createInitialState(): ReviewState;

  /** Computes the next state and the next review date given a grade. Pure. */
  schedule(state: ReviewState, grade: ReviewGrade, now?: Date): ReviewResult;

  /**
   * Optional: previews the outcome of every possible grade without applying it, useful to show
   * the user "if you say 'good' it'll come back in 4 days" before they decide.
   */
  preview?(state: ReviewState, now?: Date): Record<ReviewGrade, ReviewResult>;
}

/**
 * SM-2 — Didact's default spaced-repetition algorithm.
 *
 * Source: `specs/education-components/research.md` Question 4. Formulas verified against:
 * - https://www.supermemo.com/en/archives1990-2015/english/ol/sm2 (original specification)
 * - https://en.wikipedia.org/wiki/SM-2_(algorithm)
 *
 * Why SM-2 is the default (research.md P4):
 * - ~40-60 lines of pure arithmetic, zero external dependencies.
 * - 35+ years in production (SuperMemo, Anki until 2023, and still an option today).
 * - "Medium" evidence in research.md's table (vs. "high" for FSRS, but FSRS costs 100-250 lines
 *   and an external library choice — see `fsrs.ts`).
 *
 * Algorithm parameters (verified against the sources above):
 * - Initial easiness factor (EF): 2.5, with a floor of 1.3 (never goes below that).
 * - Answer quality rating q in [0,5] in the original specification; this module derives it from
 *   the `ReviewGrade` vocabulary in `types.ts` (again/hard/good/easy) to keep a single rating
 *   scale across the whole library (see `SM2_GRADE_TO_QUALITY` below).
 * - q >= 3 (success): the repetition counter grows and the interval (I) grows — I(1)=1 day,
 *   I(2)=6 days, and thereafter I(n) = round(I(n-1) * EF).
 * - q < 3 (failure): the repetition counter resets to 0 and the interval goes back to 1 day.
 *
 * The easiness factor is recomputed on EVERY review (both success and failure), per the
 * canonical Wikipedia pseudocode, using:
 *
 *     EF' = EF + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02))     clamped to a floor of 1.3
 *
 * The original SuperMemo write-up (step 6) is sometimes read as "don't change EF on a failed
 * repetition", but the widely-implemented reading (Wikipedia, most open-source SM-2 ports) applies
 * the EF update unconditionally — which is also what makes the documented 1.3 floor reachable at
 * all (a "good"/"easy"-only EF update can never decrease EF, so the floor would be dead code).
 * Didact follows the unconditional form so that repeated "again"/"hard" grades genuinely drive EF
 * down toward the 1.3 floor, matching how a learner who keeps failing a card should see it come
 * back ever more often rather than the interval creeping up.
 *
 * Persistence contract (RF-2): `schedule` is a pure function of (state, grade, now). It never
 * reads or writes storage; it returns the next opaque `state` for the consumer to persist wherever
 * it likes, plus the `dueAt` date the card next becomes due. Same (state, grade, now) always
 * produces the same result.
 */

import type {
  ReviewGrade,
  ReviewResult,
  ReviewState,
  SpacedRepetitionScheduler,
} from "@/lib/didact/spaced-repetition/types";

/** Internal shape of SM-2 state, see research.md P4 (algorithm table). */
export interface SM2State extends ReviewState {
  /** Number of consecutive successful repetitions (q >= 3). Resets to 0 on a failure. */
  repetitions: number;
  /** Easiness factor. Initial 2.5, floor 1.3. */
  easinessFactor: number;
  /** Current interval in days until the next review. */
  intervalDays: number;
}

const INITIAL_EASINESS_FACTOR = 2.5;
const MINIMUM_EASINESS_FACTOR = 1.3;
const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mapping from `ReviewGrade` (the library's common vocabulary) to the q∈[0,5] quality scale of
 * the original SM-2 specification. "again"/"hard" fall below the q=3 threshold (failure, resets
 * repetitions); "good"/"easy" clear it (success, grows the interval).
 */
export const SM2_GRADE_TO_QUALITY: Record<ReviewGrade, number> = {
  again: 0,
  hard: 2,
  good: 4,
  easy: 5,
};

/** Success threshold on the q∈[0,5] scale (q >= 3 is a successful recall). */
const SUCCESS_QUALITY_THRESHOLD = 3;

/**
 * Type guard: is this opaque `ReviewState` shaped like SM-2 state? Used so `schedule` can accept a
 * plain `ReviewState` (the agnostic interface's type) but fail loudly if handed something that
 * clearly is not SM-2 state, instead of silently computing on `NaN`.
 */
function isSM2State(state: ReviewState): state is SM2State {
  return (
    typeof state.repetitions === "number" &&
    typeof state.easinessFactor === "number" &&
    typeof state.intervalDays === "number"
  );
}

/** Recompute the easiness factor from the previous EF and the quality grade, clamped to the floor. */
function nextEasinessFactor(previous: number, quality: number): number {
  const updated = previous + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02));
  return Math.max(MINIMUM_EASINESS_FACTOR, updated);
}

/**
 * SM-2 scheduler. Pure arithmetic, no persistence — the default `SpacedRepetitionScheduler` for
 * Didact retrieval-practice flows (`@didact/core`, RF-2).
 */
export const sm2Scheduler: SpacedRepetitionScheduler = {
  createInitialState(): SM2State {
    return {
      repetitions: 0,
      easinessFactor: INITIAL_EASINESS_FACTOR,
      intervalDays: 0,
    };
  },

  schedule(state: ReviewState, grade: ReviewGrade, now: Date = new Date()): ReviewResult {
    if (!isSM2State(state)) {
      throw new TypeError(
        "@didact/spaced-repetition/sm2: schedule() received a state that is not SM-2 state " +
          "(expected numeric repetitions/easinessFactor/intervalDays). Did you seed it from a " +
          "different scheduler? Use sm2Scheduler.createInitialState() for new cards.",
      );
    }

    const quality = SM2_GRADE_TO_QUALITY[grade];
    const easinessFactor = nextEasinessFactor(state.easinessFactor, quality);

    let repetitions: number;
    let intervalDays: number;

    if (quality >= SUCCESS_QUALITY_THRESHOLD) {
      // Successful recall: grow the repetition count and the interval.
      repetitions = state.repetitions + 1;
      if (repetitions === 1) {
        intervalDays = 1;
      } else if (repetitions === 2) {
        intervalDays = 6;
      } else {
        intervalDays = Math.round(state.intervalDays * easinessFactor);
      }
    } else {
      // Failure: restart the repetition schedule from the beginning (I(1) = 1 day).
      repetitions = 0;
      intervalDays = 1;
    }

    const nextState: SM2State = { repetitions, easinessFactor, intervalDays };
    const dueAt = new Date(now.getTime() + intervalDays * MILLISECONDS_PER_DAY);

    return { state: nextState, dueAt };
  },

  preview(state: ReviewState, now: Date = new Date()): Record<ReviewGrade, ReviewResult> {
    return {
      again: this.schedule(state, "again", now),
      hard: this.schedule(state, "hard", now),
      good: this.schedule(state, "good", now),
      easy: this.schedule(state, "easy", now),
    };
  },
};

/** Exported so consumers/tests can reference the documented EF floor without re-deriving it. */
export const SM2_MINIMUM_EASINESS_FACTOR = MINIMUM_EASINESS_FACTOR;
/** Exported so consumers/tests can reference the documented initial EF without re-deriving it. */
export const SM2_INITIAL_EASINESS_FACTOR = INITIAL_EASINESS_FACTOR;
